# Install dependencies


from roboflow import Roboflow
from google.colab import files
import cv2
import matplotlib.pyplot as plt

# ✅ Roboflow Authentication
rf = Roboflow(api_key="DFlrjZHolOe8aC38zXZS")  # Your API Key
project = rf.workspace("ranjita-infb1").project("cavity-detection-pe9t4")
model = project.version(1).model

# ✅ Upload Image
uploaded = files.upload()
image_path = list(uploaded.keys())[0]

# ✅ Predict with Roboflow model
result = model.predict(image_path, confidence=40).json()

# ✅ Load image using OpenCV
image = cv2.imread(image_path)

# ✅ Extract predictions (bounding boxes)
detections = []
for pred in result['predictions']:
    x, y = pred['x'], pred['y']
    w, h = pred['width'], pred['height']
    class_name = pred['class']

    # Bounding box
    x_min = int(x - w / 2)
    x_max = int(x + w / 2)
    y_min = int(y - h / 2)
    y_max = int(y + h / 2)

    detections.append({'class': class_name, 'x_min': x_min, 'x_max': x_max, 'y_min': y_min, 'y_max': y_max})

    # Draw boxes
    cv2.rectangle(image, (x_min, y_min), (x_max, y_max), (0, 255, 0), 2)
    cv2.putText(image, class_name, (x_min, y_min - 10), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (0, 255, 0), 2)

# ✅ Sort teeth horizontally
detections = sorted(detections, key=lambda d: d['x_min'])

# ✅ Calculate gaps between consecutive teeth
gaps = []
for i in range(len(detections)-1):
    gap = detections[i+1]['x_min'] - detections[i]['x_max']
    gaps.append(gap)

# ✅ Annotate gaps on image
for i in range(len(gaps)):
    x_pos = detections[i]['x_max'] + gaps[i] // 2
    y_pos = (detections[i]['y_min'] + detections[i]['y_max']) // 2
    cv2.putText(image, f"{gaps[i]}px", (x_pos, y_pos), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 0, 0), 2)

# ✅ Show image with annotations
plt.figure(figsize=(10, 10))
plt.imshow(cv2.cvtColor(image, cv2.COLOR_BGR2RGB))
plt.axis('off')
plt.title("Teeth with Gaps Measured")
plt.show()

# ✅ Print gap data
print("Gaps between consecutive teeth (in pixels):", gaps)

