# --- Imports ---
from roboflow import Roboflow
from google.colab import files
import cv2, os
import numpy as np
import matplotlib.pyplot as plt

# --- Upload image ---
uploaded = files.upload()
# pick the *last* uploaded file (in case of duplicates like teeth (3).jpeg)
image_path = list(uploaded.keys())[-1]
print("Using image:", image_path)

# --- Roboflow auth/model ---
rf = Roboflow(api_key="DFlrjZHolOe8aC38zXZS")  # <-- consider rotating later
project = rf.workspace("ranjita-infb1").project("cavity-detection-pe9t4")
model = project.version(1).model

# --- Run inference (Instance Segmentation: no overlap param) ---
pred_json = model.predict(image_path, confidence=40).json()

# --- Load original image ---
image = cv2.imread(image_path)
if image is None:
    raise RuntimeError(f"Failed to load: {image_path}")
H, W = image.shape[:2]

# --- Parse predictions into boxes ---
detections = []
for pred in pred_json["predictions"]:
    # if you only want a certain class, filter here:
    # if pred['class'] != "tooth": continue
    x, y = pred["x"], pred["y"]
    w, h = pred["width"], pred["height"]
    conf = pred.get("confidence", 1.0)
    cls  = pred["class"]

    x_min = max(int(x - w/2), 0)
    x_max = min(int(x + w/2), W-1)
    y_min = max(int(y - h/2), 0)
    y_max = min(int(y + h/2), H-1)

    detections.append({
        "class": cls,
        "conf": conf,
        "x_min": x_min, "x_max": x_max,
        "y_min": y_min, "y_max": y_max,
        "cx": int(x), "cy": int(y)
    })

if not detections:
    raise ValueError("No detections returned from model. Try lower confidence or another image.")

# --- Optional: filter by min box size to drop noise ---
MIN_W, MIN_H = 10, 10
detections = [d for d in detections if (d["x_max"]-d["x_min"]>=MIN_W and d["y_max"]-d["y_min"]>=MIN_H)]
if not detections:
    raise ValueError("All detections filtered out (too small). Relax MIN_W/MIN_H.")

# --- Sort left→right (upper arch assumed roughly horizontal) ---
detections.sort(key=lambda d: d["x_min"])

# --- Compute gaps in pixels between adjacent boxes ---
gaps = []
for i in range(len(detections)-1):
    right_edge = detections[i]["x_max"]
    next_left  = detections[i+1]["x_min"]
    gap = next_left - right_edge
    if gap < 0:   # overlapping boxes: set to 0
        gap = 0
    gaps.append(gap)

# --- Draw boxes & labels ---
for i, d in enumerate(detections):
    cv2.rectangle(image, (d["x_min"], d["y_min"]), (d["x_max"], d["y_max"]), (0,255,0), 2)
    label = f"T{i+1}"
    cv2.putText(image, label, (d["x_min"], max(d["y_min"]-5, 0)),
                cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0,255,0), 1, cv2.LINE_AA)

# --- Draw gap text between teeth ---
for i, gap in enumerate(gaps):
    # Midpoint between two teeth horizontally; pick mid Y between their centers
    mid_x = (detections[i]["x_max"] + detections[i+1]["x_min"]) // 2
    mid_y = (detections[i]["cy"] + detections[i+1]["cy"]) // 2
    cv2.putText(image, f"{gap}px", (int(mid_x), int(mid_y)),
                cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255,0,0), 1, cv2.LINE_AA)

# --- Show annotated result ---
plt.figure(figsize=(8,5))
plt.imshow(cv2.cvtColor(image, cv2.COLOR_BGR2RGB))
plt.title("Teeth Detected & Gaps (px)")
plt.axis("off")
plt.show()

# --- Print numeric report ---
print("\n🦷 Gap Measurements (pixels)")
for i, gap in enumerate(gaps):
    print(f"Gap between Tooth {i+1} and Tooth {i+2}: {gap} px")
# --- After computing gaps and detections as before ---
total_teeth = len(detections)
avg_gap = np.mean(gaps) if gaps else 0

# RULE-BASED LOGIC:
# - If any gap > 15 px OR total teeth < 20, suggest cap
# - Else no cap required
cap_needed = False
reason = ""
if total_teeth < 20:
    cap_needed = True
    reason = "Missing teeth detected"
elif avg_gap > 15:
    cap_needed = True
    reason = "Large gaps detected"

suggestion = "Cap Needed" if cap_needed else "Cap Not Required"

# ✅ Show report
print("\n🦷 TEETH ANALYSIS REPORT")
print(f"• Total Teeth Detected: {total_teeth}")
print(f"• Average Gap: {avg_gap:.2f}px")
print(f"• Largest Gap: {max(gaps) if gaps else 0}px")
print(f"• Dental Cap Suggestion: {suggestion} ({reason if reason else 'Teeth alignment looks fine'})")

# --- Show final image with info ---
plt.figure(figsize=(8,5))
plt.imshow(cv2.cvtColor(image, cv2.COLOR_BGR2RGB))
plt.title(f"Teeth Detected: {total_teeth} | {suggestion}")
plt.axis("off")
plt.show()

