import cv2
import numpy as np
import matplotlib.pyplot as plt
from roboflow import Roboflow
from shapely.geometry import Polygon

# =============================
# STEP 3: Connect to Roboflow
# =============================
API_KEY = "DFlrjZHolOe8aC38zXZS"  # Replace with your Roboflow API key
rf = Roboflow(api_key=API_KEY)
project = rf.workspace("ranjita-infb1").project("cavity-detection-pe9t4")
model = project.version(1).model

# =============================
# STEP 4: Upload Image
# =============================
from google.colab import files
uploaded = files.upload()
image_path = list(uploaded.keys())[0]

# =============================
# STEP 5: Run YOLOv8 Segmentation
# =============================
result = model.predict(image_path, confidence=40).json()
image = cv2.imread(image_path)

# =============================
# STEP 6: Extract Teeth Masks and Calculate Gaps
# =============================
detections = []
for prediction in result["predictions"]:
    if "points" in prediction:  # Polygon points for instance segmentation
        points = np.array([[p['x'], p['y']] for p in prediction['points']], dtype=np.int32)
        polygon = Polygon(points)
        x_min = min([p[0] for p in points])
        x_max = max([p[0] for p in points])
        center_x = (x_min + x_max) / 2
        detections.append({"polygon": polygon, "center_x": center_x, "points": points})

# Sort teeth from left to right
detections = sorted(detections, key=lambda d: d["center_x"])

# =============================
# Calculate Gaps Between Teeth
# =============================
gaps = []
for i in range(len(detections)-1):
    gap = detections[i+1]["polygon"].bounds[0] - detections[i]["polygon"].bounds[2]
    gaps.append(max(gap, 0))  # Avoid negative gap

# =============================
# Draw Results
# =============================
output = image.copy()
for det in detections:
    cv2.polylines(output, [det["points"]], isClosed=True, color=(255,0,255), thickness=2)

# Display gap measurements
for i, gap in enumerate(gaps):
    mid_x = int((detections[i]["center_x"] + detections[i+1]["center_x"]) / 2)
    mid_y = int((detections[i]["polygon"].bounds[1] + detections[i]["polygon"].bounds[3]) / 2)
    cv2.putText(output, f"{gap:.1f}px", (mid_x, mid_y), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 0, 0), 2)

# =============================
# STEP 7: Alignment Check
# =============================
alignment_diff = np.std([d["center_x"] for d in detections])
alignment = "Normal" if alignment_diff < 15 else "Distracted"

# =============================
# STEP 8: Cap Suggestion
# =============================
if any(g > 15 for g in gaps) or alignment == "Distracted":
    suggestion = "Cap May Be Needed"
else:
    suggestion = "Cap Not Required"

# =============================
# STEP 9: Display Output
# =============================
plt.figure(figsize=(8,6))
plt.imshow(cv2.cvtColor(output, cv2.COLOR_BGR2RGB))
plt.title("Teeth Segmentation with Gaps")
plt.axis('off')
plt.show()

print("🦷 Teeth Analysis:")
print(f"• Alignment: {alignment}")
print(f"• Gaps Between Teeth: {gaps}")
print(f"• Dental Suggestion: {suggestion}")

import cv2
import numpy as np
from shapely.geometry import Polygon

def detect_hygiene_products(image_path):
    # Load image
    image = cv2.imread(image_path)
    output = image.copy()

    # Convert to HSV color space
    hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)

    # Define color ranges for hygiene products (adjust as needed)
    lower_white = np.array([0, 0, 200])
    upper_white = np.array([180, 30, 255])

    # Create mask
    mask = cv2.inRange(hsv, lower_white, upper_white)

    # Find contours
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    detections = []
    min_product_area = 500  # Minimum area to be considered a product

    for contour in contours:
        area = cv2.contourArea(contour)
        if area > min_product_area:
            polygon = Polygon([point[0] for point in contour])
            x, y, w, h = cv2.boundingRect(contour)
            center_x = x + w // 2

            detections.append({
                "polygon": polygon,
                "center_x": center_x,
                "width": w
            })

    # Sort detections by x-position
    detections.sort(key=lambda x: x["center_x"])

    # Calculate gaps between products
    gaps = []
    for i in range(len(detections) - 1):
        gap = detections[i+1]["center_x"] - detections[i]["center_x"] - (detections[i]["width"] / 2) - (detections[i+1]["width"] / 2)
        gaps.append(gap)

    # Display gap measurements
    for i, gap in enumerate(gaps):
        mid_x = int((detections[i]["center_x"] + detections[i+1]["center_x"]) / 2)
        mid_y = int((detections[i]["polygon"].bounds[1] + detections[i]["polygon"].bounds[3]) / 2)
        cv2.putText(output, f"{gap:.1f}px", (mid_x, mid_y), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (255, 0, 0), 2)

    # Cap suggestion logic
    if len(gaps) > 0:
        avg_gap = sum(gaps) / len(gaps)
        cap_size = "Medium" if avg_gap < 100 else "Large"
        cv2.putText(output, f"Suggested Cap: {cap_size}", (20, 40),
                   cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)

    return output

# Example usage
result_image = detect_hygiene_products("hygiene_products.jpg")
cv2.imshow("Result", result_image)
cv2.waitKey(0)
cv2.destroyAllWindows()

