# =============================
# IMPORTS
# =============================
from roboflow import Roboflow
from google.colab import files
import cv2, json
import numpy as np
import matplotlib.pyplot as plt
from shapely.geometry import Polygon
from sklearn.cluster import KMeans

# =============================
# CONFIG
# =============================
API_KEY = "DFlrjZHolOe8aC38zXZS"   # <-- rotate later; visible here
WORKSPACE = "ranjita-infb1"
PROJECT   = "cavity-detection-pe9t4"
VERSION   = 1
CONFIDENCE = 40       # %
MIN_BOX_WH = 10       # px to ignore tiny noise
GAP_ALERT_PX = 15     # px threshold for "large" gap (tune per resolution)

# =============================
# LOAD MODEL
# =============================
rf = Roboflow(api_key=API_KEY)
project = rf.workspace(WORKSPACE).project(PROJECT)
model = project.version(VERSION).model

# =============================
# UPLOAD IMAGE
# =============================
uploaded = files.upload()
image_path = list(uploaded.keys())[-1]
print("Using image:", image_path)

# =============================
# INFERENCE (Instance Segmentation)
# =============================
pred_json = model.predict(image_path, confidence=CONFIDENCE).json()

# Load original image
img = cv2.imread(image_path)
if img is None:
    raise RuntimeError(f"Could not read {image_path}")
H, W = img.shape[:2]

# =============================
# PARSE PREDICTIONS
# =============================
detections = []
for p in pred_json["predictions"]:
    cls = p.get("class", "?")
    conf = p.get("confidence", 1.0)
    w = p.get("width", 0)
    h = p.get("height", 0)
    if w < MIN_BOX_WH or h < MIN_BOX_WH:
        continue  # skip tiny blobs

    if "points" in p and p["points"]:
        pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.int32)
    else:
        # fallback to box if no polygon
        x, y = p["x"], p["y"]
        x_min = int(x - w/2); x_max = int(x + w/2)
        y_min = int(y - h/2); y_max = int(y + h/2)
        pts = np.array([[x_min,y_min],[x_max,y_min],[x_max,y_max],[x_min,y_max]], dtype=np.int32)

    poly = Polygon(pts)
    if poly.area <= 0:
        continue

    # derive metrics
    bx_min, by_min, bx_max, by_max = poly.bounds
    cx = (bx_min + bx_max)/2
    cy = (by_min + by_max)/2

    detections.append({
        "class": cls,
        "conf": conf,
        "poly": poly,
        "pts": pts,
        "cx": cx,
        "cy": cy,
        "bx_min": bx_min, "bx_max": bx_max,
        "by_min": by_min, "by_max": by_max
    })

if not detections:
    raise ValueError("No usable detections.")

# =============================
# GROUP INTO ARCHES (UPPER vs LOWER)
# =============================
# Some datasets detect just one arch; guard for that
if len(detections) >= 4:  # try clustering
    y_coords = np.array([[d["cy"]] for d in detections])
    if len(detections) > 1:
        k = 2 if len(detections) >= 6 else 1  # only cluster if enough
    else:
        k = 1
    if k == 2:
        km = KMeans(n_clusters=2, n_init=5, random_state=0)
        labels = km.fit_predict(y_coords)
    else:
        labels = np.zeros(len(detections), dtype=int)
else:
    labels = np.zeros(len(detections), dtype=int)

# build arches dict
arches = {}
for d, lab in zip(detections, labels):
    arches.setdefault(lab, []).append(d)

# sort label order top-to-bottom (so label 0 = upper)
lab_sorted = sorted(arches.keys(), key=lambda L: np.mean([d["cy"] for d in arches[L]]))
arches = {new_i: arches[lab_sorted[new_i]] for new_i in range(len(lab_sorted))}

# =============================
# FUNCTION: compute gaps within one arch
# =============================
def compute_gaps_one_arch(dlist):
    # sort teeth left -> right
    dlist = sorted(dlist, key=lambda d: d["cx"])
    gaps = []
    for i in range(len(dlist)-1):
        gap = dlist[i+1]["bx_min"] - dlist[i]["bx_max"]
        if gap < 0:
            gap = 0
        gaps.append(gap)
    return dlist, gaps

# =============================
# ANALYZE EACH ARCH
# =============================
annot = img.copy()
report_lines = []
cap_flags = []

colors = [(255,0,255),(0,255,255)]  # upper/lower polys
for arch_id, dlist in arches.items():
    d_sorted, gaps = compute_gaps_one_arch(dlist)

    # draw polygons
    col = colors[arch_id % len(colors)]
    for idx, d in enumerate(d_sorted):
        cv2.polylines(annot, [d["pts"]], True, col, 2)
        cv2.putText(annot, f"A{arch_id+1}T{idx+1}",
                    (int(d["bx_min"]), max(int(d["by_min"])-5,0)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.4, col, 1, cv2.LINE_AA)

    # annotate gaps
    for i, g in enumerate(gaps):
        mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i+1]["bx_min"]) / 2)
        mid_y = int((d_sorted[i]["cy"] + d_sorted[i+1]["cy"]) / 2)
        cv2.putText(annot, f"{g:.0f}px", (mid_x, mid_y),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.45, (255,0,0), 1, cv2.LINE_AA)

    # arch-level metrics
    avg_gap = np.mean(gaps) if gaps else 0
    max_gap = np.max(gaps) if gaps else 0
    cap_needed = bool(max_gap > GAP_ALERT_PX)
    cap_flags.append(cap_needed)

    report_lines.append(f"Arch {arch_id+1}: Teeth={len(d_sorted)} AvgGap={avg_gap:.1f}px MaxGap={max_gap:.1f}px CapFlag={cap_needed}")

# =============================
# GLOBAL ALIGNMENT
# =============================
# simple: std of all centers; better: poly fit
all_cx = [d["cx"] for d in detections]
alignment_std = np.std(all_cx)
alignment = "Normal" if alignment_std < 25 else "Distracted"

# global cap suggestion
global_cap = "Cap May Be Needed" if (any(cap_flags) or alignment == "Distracted") else "Cap Not Required"

# =============================
# SHOW RESULT
# =============================
plt.figure(figsize=(10,6))
plt.imshow(cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
plt.title(f"Teeth Segmentation | {global_cap}")
plt.axis('off')
plt.show()

print("\n--- Teeth Gap & Cap Report ---")
for line in report_lines:
    print(line)
print(f"Alignment: {alignment}")
print(f"Dental Suggestion: {global_cap}")

