from roboflow import Roboflow
from google.colab import files
import cv2, json, math
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from shapely.geometry import Polygon
from sklearn.cluster import KMeans

# =========================================
# CONFIG - EDIT THESE
# =========================================
API_KEY        = "DFlrjZHolOe8aC38zXZS"  # <-- rotate later for safety
WORKSPACE      = "ranjita-infb1"
PROJECT        = "cavity-detection-pe9t4"
VERSION        = 1
CONFIDENCE     = 40       # model confidence %
MIN_BOX_WH     = 10       # ignore tiny blobs
GAP_ALERT_PX   = 15       # gap considered "large"
ALIGN_ALERT_PX = 25       # std-of-centers threshold for distraction

# --- Pixel→mm calibration (optional) ---
# If you know a real tooth width (mm) and which one to use, set these:
KNOWN_MM_PER_TOOTH = None  # e.g., 8.5  (central incisor average mm)
USE_REF_TOOTH_IDX  = 0     # use first detected tooth in each arch for scaling (if KNOWN_MM_PER_TOOTH set)
# If KNOWN_MM_PER_TOOTH is None, mm columns will be NaN.

# =========================================
# UPLOAD IMAGE
# =========================================
uploaded = files.upload()
image_path = list(uploaded.keys())[-1]  # most recent
print("Using image:", image_path)

# =========================================
# CONNECT ROBOFLOW + LOAD MODEL
# =========================================
rf = Roboflow(api_key=API_KEY)
project = rf.workspace(WORKSPACE).project(PROJECT)
model = project.version(VERSION).model

# =========================================
# RUN INFERENCE (Instance Segmentation)
# =========================================
pred_json = model.predict(image_path, confidence=CONFIDENCE).json()

# =========================================
# LOAD IMAGE
# =========================================
img = cv2.imread(image_path)
if img is None:
    raise RuntimeError(f"Could not read {image_path}")
H, W = img.shape[:2]

# =========================================
# PARSE PREDICTIONS → POLYGONS
# =========================================
detections = []
for p in pred_json["predictions"]:
    cls  = p.get("class", "?")
    conf = p.get("confidence", 1.0)
    w    = p.get("width", 0)
    h    = p.get("height", 0)
    if w < MIN_BOX_WH or h < MIN_BOX_WH:
        continue

    # polygon if available; else fallback box
    if "points" in p and p["points"]:
        pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
    else:
        x, y = p["x"], p["y"]
        x_min = x - w/2; x_max = x + w/2
        y_min = y - h/2; y_max = y + h/2
        pts = np.array([[x_min,y_min],[x_max,y_min],[x_max,y_max],[x_min,y_max]], dtype=np.float32)

    poly = Polygon(pts)
    if not poly.is_valid or poly.area <= 0:
        continue

    bx_min, by_min, bx_max, by_max = poly.bounds
    cx = (bx_min + bx_max) / 2.0
    cy = (by_min + by_max) / 2.0
    w_px = bx_max - bx_min
    h_px = by_max - by_min
    area_px = poly.area

    detections.append({
        "class": cls,
        "conf": conf,
        "poly": poly,
        "pts": pts.astype(int),
        "cx": cx, "cy": cy,
        "bx_min": bx_min, "bx_max": bx_max,
        "by_min": by_min, "by_max": by_max,
        "w_px": w_px, "h_px": h_px,
        "area_px": area_px
    })

if not detections:
    raise ValueError("No usable detections returned from model. Try lowering confidence or using a clearer image.")

# =========================================
# GROUP INTO ARCHES (upper vs lower) via Y clustering
# =========================================
if len(detections) >= 6:
    y_coords = np.array([[d["cy"]] for d in detections])
    km = KMeans(n_clusters=2, n_init=5, random_state=0)
    labels = km.fit_predict(y_coords)
else:
    labels = np.zeros(len(detections), dtype=int)

# reorder labels top=arch1 bottom=arch2
arch_map = {}
for d, lab in zip(detections, labels):
    arch_map.setdefault(lab, []).append(d)

label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
arches = {new_id: arch_map[old_id] for new_id, old_id in enumerate(label_order)}

# =========================================
# HELPER: compute gaps in one arch (sorted L→R)
# =========================================
def compute_arch_metrics(dlist):
    d_sorted = sorted(dlist, key=lambda d: d["cx"])
    gaps = []
    for i in range(len(d_sorted)-1):
        gap = d_sorted[i+1]["bx_min"] - d_sorted[i]["bx_max"]
        if gap < 0: gap = 0
        gaps.append(gap)
    return d_sorted, gaps

# =========================================
# PER-ARCH PROCESSING + DATAFRAMES
# =========================================
teeth_rows = []
gap_rows   = []
annot = img.copy()
arch_colors = [(255,0,255), (0,255,255)]  # BGR

for arch_id, dlist in arches.items():
    d_sorted, gaps = compute_arch_metrics(dlist)
    col = arch_colors[arch_id % len(arch_colors)]

    # optional pixel→mm scale using reference tooth width
    px_per_mm = None
    if KNOWN_MM_PER_TOOTH is not None and len(d_sorted) > USE_REF_TOOTH_IDX:
        ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
        if ref_w_px > 0:
            px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH  # px per mm

    # draw + record metrics
    for idx, d in enumerate(d_sorted):
        cv2.polylines(annot, [d["pts"]], True, col, 2)
        label = f"A{arch_id+1}T{idx+1}"
        cv2.putText(annot, label,
                    (int(d["bx_min"]), max(int(d["by_min"])-5,0)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.5, col, 1, cv2.LINE_AA)

        teeth_rows.append({
            "arch_id": arch_id+1,
            "tooth_idx": idx+1,
            "class": d["class"],
            "confidence": d["conf"],
            "cx_px": d["cx"],
            "cy_px": d["cy"],
            "width_px": d["w_px"],
            "height_px": d["h_px"],
            "area_px": d["area_px"],
            "width_mm": (d["w_px"]/px_per_mm) if px_per_mm else np.nan,
            "height_mm": (d["h_px"]/px_per_mm) if px_per_mm else np.nan,
            "area_mm2": ((d["area_px"]/(px_per_mm**2)) if px_per_mm else np.nan)
        })

    # draw gap labels + record gap rows
    for i, g in enumerate(gaps):
        mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i+1]["bx_min"]) / 2)
        mid_y = int((d_sorted[i]["cy"] + d_sorted[i+1]["cy"]) / 2)
        text = f"{g:.0f}px"
        if px_per_mm:
            gmm = g/px_per_mm
            text = f"{g:.0f}px|{gmm:.1f}mm"
        else:
            gmm = np.nan

        cv2.putText(annot, text, (mid_x, mid_y),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255,0,0), 1, cv2.LINE_AA)

        gap_rows.append({
            "arch_id": arch_id+1,
            "left_tooth_idx": i+1,
            "right_tooth_idx": i+2,
            "gap_px": g,
            "gap_mm": gmm
        })

# =========================================
# ALIGNMENT SCORE (all detected teeth)
# =========================================
all_cx = np.array([d["cx"] for d in detections])
align_std = np.std(all_cx)
alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted"

# =========================================
# CAP SUGGESTION RULE
# =========================================
any_large_gap = any(row["gap_px"] > GAP_ALERT_PX for row in gap_rows)
cap_suggestion = "Cap May Be Needed" if (any_large_gap or alignment == "Distracted") else "Cap Not Required"

# =========================================
# BUILD DATAFRAMES
# =========================================
df_teeth = pd.DataFrame(teeth_rows)
df_gaps  = pd.DataFrame(gap_rows)

# =========================================
# SAVE CSVs
# =========================================
df_teeth.to_csv("teeth_metrics.csv", index=False)
df_gaps.to_csv("teeth_gap_metrics.csv", index=False)

# =========================================
# SHOW ANNOTATED IMAGE
# =========================================
plt.figure(figsize=(10,6))
plt.imshow(cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
plt.title(f"Teeth Segmentation | {alignment} | {cap_suggestion}")
plt.axis('off')
plt.show()

# =========================================
# PRINT SUMMARY
# =========================================
print("\n=== TEETH SUMMARY ===")
print(df_teeth)

print("\n=== GAP SUMMARY ===")
print(df_gaps)

print("\n=== OVERALL ASSESSMENT ===")
print(f"Alignment Score (std x-centers): {align_std:.2f}px → {alignment}")
print(f"Any Gap > {GAP_ALERT_PX}px: {any_large_gap}")
print(f"Dental Cap Suggestion: {cap_suggestion}")

# =========================================
# DOWNLOAD LINKS
# =========================================
from google.colab import files
print("\nDownload per-tooth metrics CSV:")
files.download("teeth_metrics.csv")
print("Download gap metrics CSV:")
files.download("teeth_gap_metrics.csv")

