from roboflow import Roboflow
from google.colab import files
import cv2
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from shapely.geometry import Polygon
from sklearn.cluster import KMeans

# =========================================
# CONFIG
# =========================================
API_KEY        = "DFlrjZHolOe8aC38zXZS"   # <-- rotate for production
WORKSPACE      = "ranjita-infb1"
PROJECT        = "cavity-detection-pe9t4"
VERSION        = 1
CONFIDENCE     = 40
MIN_BOX_WH     = 10
GAP_ALERT_PX   = 15
ALIGN_ALERT_PX = 25

# Optional: Pixel→mm calibration
KNOWN_MM_PER_TOOTH = None  # e.g., 8.5 mm if known
USE_REF_TOOTH_IDX  = 0     # index for reference tooth width

# =========================================
# UPLOAD IMAGE
# =========================================
uploaded = files.upload()
image_path = list(uploaded.keys())[-1]
print("Using image:", image_path)

# =========================================
# CONNECT ROBOFLOW + LOAD MODEL
# =========================================
rf = Roboflow(api_key=API_KEY)
project = rf.workspace(WORKSPACE).project(PROJECT)
model = project.version(VERSION).model

# =========================================
# RUN INFERENCE
# =========================================
pred_json = model.predict(image_path, confidence=CONFIDENCE).json()

# =========================================
# LOAD IMAGE
# =========================================
img = cv2.imread(image_path)
if img is None:
    raise RuntimeError(f"Could not read {image_path}")
H, W = img.shape[:2]

# =========================================
# PARSE PREDICTIONS
# =========================================
detections = []
for p in pred_json["predictions"]:
    cls = p.get("class", "?")
    conf = p.get("confidence", 1.0)
    w = p.get("width", 0)
    h = p.get("height", 0)
    if w < MIN_BOX_WH or h < MIN_BOX_WH:
        continue

    # Polygon or box
    if "points" in p and p["points"]:
        pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
    else:
        x, y = p["x"], p["y"]
        x_min, x_max = x - w / 2, x + w / 2
        y_min, y_max = y - h / 2, y + h / 2
        pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)

    poly = Polygon(pts)
    if not poly.is_valid or poly.area <= 0:
        continue

    bx_min, by_min, bx_max, by_max = poly.bounds
    cx = (bx_min + bx_max) / 2
    cy = (by_min + by_max) / 2
    w_px = bx_max - bx_min
    h_px = by_max - by_min
    area_px = poly.area

    detections.append({
        "class": cls,
        "conf": conf,
        "pts": pts.astype(int),
        "cx": cx, "cy": cy,
        "bx_min": bx_min, "bx_max": bx_max,
        "by_min": by_min, "by_max": by_max,
        "w_px": w_px, "h_px": h_px,
        "area_px": area_px
    })

if not detections:
    raise ValueError("No teeth detected. Try a clearer image or lower confidence threshold.")

# =========================================
# GROUP INTO ARCHES
# =========================================
if len(detections) >= 6:
    y_coords = np.array([[d["cy"]] for d in detections])
    km = KMeans(n_clusters=2, n_init=5, random_state=0)
    labels = km.fit_predict(y_coords)
else:
    labels = np.zeros(len(detections), dtype=int)

arch_map = {}
for d, lab in zip(detections, labels):
    arch_map.setdefault(lab, []).append(d)

label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
arches = {new_id: arch_map[old_id] for new_id, old_id in enumerate(label_order)}

# =========================================
# PROCESS & ANALYZE
# =========================================
teeth_rows = []
gap_rows = []
annot = img.copy()
arch_colors = [(255, 0, 255), (0, 255, 255)]

for arch_id, dlist in arches.items():
    d_sorted = sorted(dlist, key=lambda d: d["cx"])
    col = arch_colors[arch_id % len(arch_colors)]

    px_per_mm = None
    if KNOWN_MM_PER_TOOTH and len(d_sorted) > USE_REF_TOOTH_IDX:
        ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
        if ref_w_px > 0:
            px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH

    for idx, d in enumerate(d_sorted):
        # Draw polygon
        cv2.polylines(annot, [d["pts"]], True, col, 2)
        label = f"A{arch_id+1}T{idx+1}"
        cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.5, col, 1, cv2.LINE_AA)

        # Show size
        size_text = f"{int(d['w_px'])}x{int(d['h_px'])} px"
        cv2.putText(annot, size_text, (int(d["bx_min"]), int(d["by_max"]) + 12),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 255, 0), 1)

        teeth_rows.append({
            "arch_id": arch_id + 1,
            "tooth_idx": idx + 1,
            "class": d["class"],
            "cx_px": d["cx"],
            "cy_px": d["cy"],
            "width_px": d["w_px"],
            "height_px": d["h_px"],
            "area_px": d["area_px"]
        })

    # Compute gaps
    for i in range(len(d_sorted) - 1):
        gap = d_sorted[i + 1]["bx_min"] - d_sorted[i]["bx_max"]
        if gap < 0: gap = 0
        mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i + 1]["bx_min"]) / 2)
        mid_y = int((d_sorted[i]["cy"] + d_sorted[i + 1]["cy"]) / 2)
        cv2.putText(annot, f"{gap:.0f}px", (mid_x, mid_y),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.5, (255, 0, 0), 1)
        gap_rows.append({
            "arch_id": arch_id + 1,
            "left_tooth_idx": i + 1,
            "right_tooth_idx": i + 2,
            "gap_px": gap
        })

# =========================================
# ALIGNMENT & CAP DECISION
# =========================================
df_teeth = pd.DataFrame(teeth_rows)
df_gaps = pd.DataFrame(gap_rows)
align_std = np.std([d["cy"] for d in detections])
alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted"
any_large_gap = any(row["gap_px"] > GAP_ALERT_PX for row in gap_rows)
cap_suggestion = "Cap May Be Needed" if (any_large_gap or alignment == "Distracted") else "Cap Not Required"

# =========================================
# DISPLAY IMAGE
# =========================================
plt.figure(figsize=(10, 6))
plt.imshow(cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
plt.title(f"Teeth Analysis | Alignment: {alignment} | {cap_suggestion}")
plt.axis('off')
plt.show()

# =========================================
# PRINT RESULTS
# =========================================
print("\n=== TOOTH SIZES ===")
print(df_teeth[["arch_id", "tooth_idx", "width_px", "height_px", "area_px"]].to_string(index=False))

print("\n=== LARGE GAPS (> {} px) ===".format(GAP_ALERT_PX))
large_gaps = df_gaps[df_gaps["gap_px"] > GAP_ALERT_PX]
if large_gaps.empty:
    print("No large gaps detected.")
else:
    print(large_gaps.to_string(index=False))

print("\n=== ALIGNMENT STATUS ===")
print(f"Alignment: {alignment}")
print(f"Dental Cap Suggestion: {cap_suggestion}")

