from roboflow import Roboflow
from google.colab import files
import cv2
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from shapely.geometry import Polygon
from sklearn.cluster import KMeans

# =========================================
# CONFIG
# =========================================
API_KEY        = "DFlrjZHolOe8aC38zXZS"   # <-- rotate / hide in production
WORKSPACE      = "ranjita-infb1"
PROJECT        = "cavity-detection-pe9t4"
VERSION        = 1
CONFIDENCE     = 40          # 0–100 scale for Roboflow .predict()
MIN_BOX_WH     = 10
GAP_ALERT_PX   = 15          # "Large" spacing gap threshold (pixels)
ALIGN_ALERT_PX = 25          # (Legacy) std-dev threshold used below (pixels)

# Extended thresholds (heuristic)
MILD_GAP_RATIO      = 0.05   # mild spacing = gap/avg_tooth_width >= 5%
LARGE_GAP_RATIO     = 0.12   # large spacing >= 12%
CROWD_MILD_RATIO    = 0.02   # crowding ratio mild
CROWD_MOD_RATIO     = 0.05   # crowding ratio moderate
CROWD_SEV_RATIO     = 0.10   # severe if >10% total overlap / total width
ALIGN_MILD_NORM     = 0.015
ALIGN_MOD_NORM      = 0.025
ALIGN_SEV_NORM      = 0.040

# Optional: Pixel→mm calibration (not used unless set)
KNOWN_MM_PER_TOOTH = None
USE_REF_TOOTH_IDX  = 0

# =========================================
# COLOR DEFINITIONS (BGR)
# =========================================
COLOR_ARCH_1      = (255, 0, 255)   # Magenta
COLOR_ARCH_2      = (0, 255, 255)   # Cyan
COLOR_GAP_LARGE   = (255, 0, 0)     # Blue (large spacing)
COLOR_GAP_MILD    = (200, 150, 0)   # Light yellowish for mild spacing
COLOR_GAP_SMALL   = (170, 170, 170) # Neutral small/normal gap
COLOR_CROWDING    = (0, 0, 255)     # Red (overlap / crowding)
COLOR_ALIGN_CURVE = (0, 255, 0)     # Green (arch baseline)
COLOR_TEXT        = (255, 255, 255)

FONT = cv2.FONT_HERSHEY_SIMPLEX

# =========================================
# UPLOAD IMAGE
# =========================================
uploaded = files.upload()
image_path = list(uploaded.keys())[-1]
print("Using image:", image_path)

# =========================================
# CONNECT ROBOFLOW + LOAD MODEL
# =========================================
rf = Roboflow(api_key=API_KEY)
project = rf.workspace(WORKSPACE).project(PROJECT)
model = project.version(VERSION).model

# =========================================
# RUN INFERENCE
# =========================================
pred_json = model.predict(image_path, confidence=CONFIDENCE).json()

# =========================================
# LOAD IMAGE
# =========================================
img = cv2.imread(image_path)
if img is None:
    raise RuntimeError(f"Could not read {image_path}")
H, W = img.shape[:2]

# =========================================
# PARSE PREDICTIONS
# =========================================
detections = []
for p in pred_json.get("predictions", []):
    cls = p.get("class", "?")
    conf = p.get("confidence", 1.0)
    w = p.get("width", 0)
    h = p.get("height", 0)
    if w < MIN_BOX_WH or h < MIN_BOX_WH:
        continue

    # Polygon or box
    if "points" in p and p["points"]:
        pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
    else:
        x, y = p["x"], p["y"]
        x_min, x_max = x - w / 2, x + w / 2
        y_min, y_max = y - h / 2, y + h / 2
        pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)

    poly = Polygon(pts)
    if not poly.is_valid or poly.area <= 0:
        continue

    bx_min, by_min, bx_max, by_max = poly.bounds
    cx = (bx_min + bx_max) / 2
    cy = (by_min + by_max) / 2
    w_px = bx_max - bx_min
    h_px = by_max - by_min
    area_px = poly.area

    detections.append({
        "class": cls,
        "conf": conf,
        "pts": pts.astype(int),
        "cx": cx, "cy": cy,
        "bx_min": bx_min, "bx_max": bx_max,
        "by_min": by_min, "by_max": by_max,
        "w_px": w_px, "h_px": h_px,
        "area_px": area_px
    })

if not detections:
    raise ValueError("No teeth detected. Try a clearer image or lower confidence threshold.")

# =========================================
# GROUP INTO ARCHES (KMeans on cy)
# =========================================
if len(detections) >= 6:
    y_coords = np.array([[d["cy"]] for d in detections])
    try:
        km = KMeans(n_clusters=2, n_init=5, random_state=0)
        labels = km.fit_predict(y_coords)
    except Exception:
        labels = np.zeros(len(detections), dtype=int)
else:
    labels = np.zeros(len(detections), dtype=int)

arch_map = {}
for d, lab in zip(detections, labels):
    arch_map.setdefault(lab, []).append(d)

# Order by vertical position
label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
arches = {new_id: arch_map[old_id] for new_id, old_id in enumerate(label_order)}

# =========================================
# PROCESS & ANALYZE
# =========================================
teeth_rows = []
gap_rows = []
annot = img.copy()
arch_colors = [COLOR_ARCH_1, COLOR_ARCH_2]

def fit_curve(teeth):
    xs = np.array([t["cx"] for t in teeth])
    ys = np.array([t["cy"] for t in teeth])
    if len(xs) >= 3:
        coeffs = np.polyfit(xs, ys, 2)
    else:
        coeffs = np.polyfit(xs, ys, 1)
    f = np.poly1d(coeffs)
    residuals = ys - f(xs)
    rms = np.sqrt(np.mean(residuals**2))
    return f, rms

arch_rms_norms = []
global_gap_ratios = []
crowd_overlaps = []  # store positive magnitudes of overlaps for crowding ratio

for arch_id, dlist in arches.items():
    d_sorted = sorted(dlist, key=lambda d: d["cx"])
    col = arch_colors[arch_id % len(arch_colors)]

    # Pixel-to-mm (optional)
    px_per_mm = None
    if KNOWN_MM_PER_TOOTH and len(d_sorted) > USE_REF_TOOTH_IDX:
        ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
        if ref_w_px > 0:
            px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH

    # Fit arch curve for alignment (per arch)
    curve, rms = fit_curve(d_sorted)
    arch_rms_norms.append(rms / H)

    # Draw curve (baseline)
    xs_curve = np.array([t["cx"] for t in d_sorted])
    if len(xs_curve) >= 2:
        x_line = np.linspace(xs_curve.min(), xs_curve.max(), 80)
        y_line = curve(x_line)
        pts_curve = np.vstack([x_line, y_line]).T.astype(int)
        for i in range(len(pts_curve) - 1):
            cv2.line(annot, tuple(pts_curve[i]), tuple(pts_curve[i + 1]), COLOR_ALIGN_CURVE, 1)

    # Draw teeth + record metrics
    for idx, d in enumerate(d_sorted):
        cv2.polylines(annot, [d["pts"]], True, col, 1)
        label = f"A{arch_id+1}T{idx+1}"
        cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 2, 0)),
                    FONT, 0.4, col, 1, cv2.LINE_AA)

        teeth_rows.append({
            "arch_id": arch_id + 1,
            "tooth_idx": idx + 1,
            "class": d["class"],
            "cx_px": d["cx"],
            "cy_px": d["cy"],
            "width_px": d["w_px"],
            "height_px": d["h_px"],
            "area_px": d["area_px"]
        })

    # Compute gaps (keep negatives for crowding)
    avg_w = np.mean([td["w_px"] for td in d_sorted]) if d_sorted else 1.0
    for i in range(len(d_sorted) - 1):
        left = d_sorted[i]
        right = d_sorted[i + 1]
        raw_gap = right["bx_min"] - left["bx_max"]   # negative => overlap (crowding)
        gap_display = raw_gap  # show actual (could be negative)
        if raw_gap < 0:
            ratio = 0  # spacing ratio not meaningful for crowding
            crowd_overlaps.append(-raw_gap)
            color_gap = COLOR_CROWDING
            text = f"{raw_gap:.0f}ov"  # overlap
        else:
            ratio = raw_gap / avg_w if avg_w > 0 else 0
            global_gap_ratios.append(ratio)
            if ratio >= LARGE_GAP_RATIO:
                color_gap = COLOR_GAP_LARGE
            elif ratio >= MILD_GAP_RATIO:
                color_gap = COLOR_GAP_MILD
            else:
                color_gap = COLOR_GAP_SMALL
            text = f"{raw_gap:.0f}px"

        mid_x = int((left["bx_max"] + right["bx_min"]) / 2)
        mid_y = int((left["cy"] + right["cy"]) / 2)
        cv2.putText(annot, text, (mid_x, mid_y),
                    FONT, 0.45, color_gap, 1, cv2.LINE_AA)

        gap_rows.append({
            "arch_id": arch_id + 1,
            "left_tooth_idx": i + 1,
            "right_tooth_idx": i + 2,
            "raw_gap_px": raw_gap,
            "spacing_ratio": ratio
        })

# =========================================
# ALIGNMENT & ORTHO DECISIONS
# =========================================
df_teeth = pd.DataFrame(teeth_rows)
df_gaps  = pd.DataFrame(gap_rows)

# Legacy simple alignment (std of cy across ALL teeth)
align_std = np.std([d["cy"] for d in detections])
legacy_alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted"

# Improved per‑arch RMS-based severity
if arch_rms_norms:
    max_align_norm = max(arch_rms_norms)
else:
    max_align_norm = 0.0

def classify_alignment(norm_val):
    if norm_val < ALIGN_MILD_NORM: return "none"
    if norm_val < ALIGN_MOD_NORM:  return "mild"
    if norm_val < ALIGN_SEV_NORM:  return "moderate"
    return "severe"

alignment_severity = classify_alignment(max_align_norm)

# Spacing severity
if global_gap_ratios:
    max_spacing_ratio = max(global_gap_ratios)
else:
    max_spacing_ratio = 0.0
if max_spacing_ratio < MILD_GAP_RATIO:
    spacing_severity = "none"
elif max_spacing_ratio < LARGE_GAP_RATIO:
    spacing_severity = "mild"
elif max_spacing_ratio < 0.20:
    spacing_severity = "moderate"
else:
    spacing_severity = "severe"

# Crowding severity (ratio = total overlap / total image width)
total_overlap = sum(crowd_overlaps)
crowd_ratio = total_overlap / W if W > 0 else 0
if crowd_ratio < CROWD_MILD_RATIO:
    crowding_severity = "none"
elif crowd_ratio < CROWD_MOD_RATIO:
    crowding_severity = "mild"
elif crowd_ratio < CROWD_SEV_RATIO:
    crowding_severity = "moderate"
else:
    crowding_severity = "severe"

# Orthodontic need heuristic
def need_ortho(spacing, crowding, align):
    sev_rank = {"none":0,"mild":1,"moderate":2,"severe":3}
    max_rank = max(sev_rank[spacing], sev_rank[crowding], sev_rank[align])
    # Need if any severe OR any two moderate OR one moderate + another mild
    conditions = sum(sev_rank[s] >= 2 for s in [spacing,crowding,align])
    if max_rank >= 3:
        return True, "Severe condition detected"
    if conditions >= 1:
        return True, "Moderate condition(s) present"
    if sum(sev_rank[s] == 1 for s in [spacing,crowding,align]) >= 2:
        return True, "Multiple mild issues"
    return False, "No significant orthodontic issue"

ortho_needed, ortho_reason = need_ortho(spacing_severity, crowding_severity, alignment_severity)

# Braces suggestions (simple mapping)
def braces_recommendations(spacing, crowding, align):
    sev_rank = {"none":0,"mild":1,"moderate":2,"severe":3}
    max_sev = max(sev_rank[spacing], sev_rank[crowding], sev_rank[align])
    rec = []
    if max_sev >= 2:  # moderate or severe somewhere
        rec.append("Metal Braces: Broad applicability, strong for complex correction.")
        rec.append("Self-Ligating Braces: Efficiency & reduced friction for crowding.")
    if 1 <= max_sev <= 2:
        rec.append("Ceramic Braces: Aesthetic option for mild–moderate cases.")
        rec.append("Clear Aligners (Invisalign): Mild–moderate spacing/crowding if compliant.")
        rec.append("Lingual Braces: Hidden behind teeth; aesthetic; more technique sensitive.")
    if not rec and not ortho_needed:
        rec.append("No braces needed: Maintain monitoring and oral hygiene.")
    return rec

braces_suggestions = braces_recommendations(spacing_severity, crowding_severity, alignment_severity)

# Cap suggestion (retain your original logic)
any_large_gap_px = any(g["raw_gap_px"] > GAP_ALERT_PX for g in gap_rows if g["raw_gap_px"] > 0)
cap_suggestion = "Cap May Be Needed" if (any_large_gap_px or legacy_alignment == "Distracted") else "Cap Not Required"

# =========================================
# LEGEND (SMALL OVERLAY)
# =========================================
def add_legend(img):
    items = [
        ("Arch 1", COLOR_ARCH_1),
        ("Arch 2", COLOR_ARCH_2),
        ("Large Spacing", COLOR_GAP_LARGE),
        ("Mild Spacing", COLOR_GAP_MILD),
        ("Normal/Small Gap", COLOR_GAP_SMALL),
        ("Crowding (Overlap)", COLOR_CROWDING),
        ("Arch Curve", COLOR_ALIGN_CURVE),
    ]
    # small transparent box top-left
    font_scale = 0.35
    thickness  = 1
    line_h     = 14
    pad        = 6
    cb_w, cb_h = 10, 8
    (H2,W2) = img.shape[:2]
    # compute width
    text_w = []
    for text,_ in items:
        (tw,_),_ = cv2.getTextSize(text, FONT, font_scale, thickness)
        text_w.append(tw)
    box_w = pad*3 + cb_w + 5 + max(text_w)
    box_h = pad*2 + line_h*len(items)
    x0, y0 = 8, 8
    overlay = img.copy()
    cv2.rectangle(overlay, (x0, y0), (x0+box_w, y0+box_h), (30,30,30), -1)
    img[:] = cv2.addWeighted(overlay, 0.65, img, 0.35, 0)
    for i,(text,color) in enumerate(items):
        y_text = y0 + pad + (i+1)*line_h - 4
        cv2.rectangle(img, (x0+pad, y_text-cb_h), (x0+pad+cb_w, y_text-2), color, -1)
        cv2.putText(img, text, (x0+pad+cb_w+5, y_text-2), FONT, font_scale, COLOR_TEXT, thickness, cv2.LINE_AA)

add_legend(annot)

# =========================================
# DISPLAY IMAGE
# =========================================
title_line = (f"Spacing:{spacing_severity} | Crowding:{crowding_severity} | "
              f"Align:{alignment_severity} | Ortho:{'Needed' if ortho_needed else 'Monitor'}")
plt.figure(figsize=(11, 6))
plt.imshow(cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
plt.title(title_line)
plt.axis('off')
plt.show()

# =========================================
# PRINT RESULTS
# =========================================
print("\n=== TOOTH SIZES ===")
print(pd.DataFrame(teeth_rows)[["arch_id","tooth_idx","width_px","height_px","area_px"]].to_string(index=False))

print("\n=== GAPS (raw, may be negative for overlap) ===")
print(pd.DataFrame(gap_rows).to_string(index=False))

print("\n=== LEGACY ALIGNMENT (std of cy) ===")
print(f"Std Dev (px): {align_std:.2f}  -> {legacy_alignment}")

print("\n=== ENHANCED SEVERITIES ===")
print(f"Spacing Severity:  {spacing_severity} (max spacing ratio = {max_spacing_ratio:.3f})")
print(f"Crowding Severity: {crowding_severity} (crowd ratio = {crowd_ratio:.3f})")
print(f"Alignment Severity: {alignment_severity} (max arch norm RMS = {max_align_norm:.4f})")

print("\n=== ORTHODONTIC NEED ===")
print(f"Needed: {ortho_needed}  Reason: {ortho_reason}")

print("\n=== CAP SUGGESTION (legacy logic) ===")
print(f"Dental Cap Suggestion: {cap_suggestion}")

print("\n=== BRACES / APPLIANCE SUGGESTIONS ===")
for s in braces_suggestions:
    print(" -", s)

print("\n=== LEGEND (Colors) ===")
print("Arch 1: Magenta | Arch 2: Cyan | Large Gap: Blue | Mild Gap: Light Yellow | Small Gap: Gray | Crowding: Red | Curve: Green")

# =========================================
# SUMMARY BLOCK
# =========================================
summary = {
    "spacing_severity": spacing_severity,
    "crowding_severity": crowding_severity,
    "alignment_severity": alignment_severity,
    "orthodontic_needed": ortho_needed,
    "orthodontic_reason": ortho_reason,
    "cap_suggestion": cap_suggestion
}
