from roboflow import Roboflow
from google.colab import files
import cv2
import numpy as np
import matplotlib.pyplot as plt
from shapely.geometry import Polygon
from sklearn.cluster import KMeans

# =========================================
# CONFIGURATION
# =========================================
API_KEY        = "DFlrjZHolOe8aC38zXZS"   # Roboflow API Key
WORKSPACE      = "ranjita-infb1"
PROJECT        = "cavity-detection-pe9t4"
VERSION        = 1
CONFIDENCE     = 40
MIN_BOX_WH     = 10
GAP_ALERT_PX   = 15   # Gap threshold
ALIGN_ALERT_PX = 25   # Alignment threshold

# Colors
COLOR_LABEL  = (0, 255, 0)   # Green = Tooth label
COLOR_GAP    = (255, 0, 0)   # Blue = Gap label
COLOR_MIS    = (0, 0, 255)   # Red = Misaligned tooth

# =========================================
# UPLOAD IMAGE
# =========================================
uploaded = files.upload()
image_path = list(uploaded.keys())[-1]
print("Using image:", image_path)

# =========================================
# CONNECT TO ROBOFLOW
# =========================================
rf = Roboflow(api_key=API_KEY)
project = rf.workspace(WORKSPACE).project(PROJECT)
model = project.version(VERSION).model

# =========================================
# RUN PREDICTION
# =========================================
pred_json = model.predict(image_path, confidence=CONFIDENCE).json()
img = cv2.imread(image_path)
if img is None:
    raise RuntimeError(f"Could not read {image_path}")

# =========================================
# PARSE PREDICTIONS
# =========================================
detections = []
for p in pred_json["predictions"]:
    w = p.get("width", 0)
    h = p.get("height", 0)
    if w < MIN_BOX_WH or h < MIN_BOX_WH:
        continue

    # Get points or fallback to bounding box
    if "points" in p and p["points"]:
        pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
    else:
        x, y = p["x"], p["y"]
        x_min, x_max = x - w / 2, x + w / 2
        y_min, y_max = y - h / 2, y + h / 2
        pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)

    poly = Polygon(pts)
    if not poly.is_valid or poly.area <= 0:
        continue

    bx_min, by_min, bx_max, by_max = poly.bounds
    cx = (bx_min + bx_max) / 2
    cy = (by_min + by_max) / 2

    detections.append({
        "pts": pts.astype(int),
        "cx": cx,
        "cy": cy,
        "bx_min": bx_min,
        "bx_max": bx_max
    })

if not detections:
    raise ValueError("No teeth detected. Try clearer image or adjust confidence.")

# =========================================
# GROUP INTO ARCHES (Upper & Lower)
# =========================================
if len(detections) >= 6:
    y_coords = np.array([[d["cy"]] for d in detections])
    km = KMeans(n_clusters=2, n_init=5, random_state=0)
    labels = km.fit_predict(y_coords)
else:
    labels = np.zeros(len(detections), dtype=int)

arch_map = {}
for d, lab in zip(detections, labels):
    arch_map.setdefault(lab, []).append(d)

label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
arches = {new_id: arch_map[old_id] for new_id, old_id in enumerate(label_order)}

# =========================================
# DETECT GAPS & ALIGNMENT
# =========================================
annot = img.copy()
important_gaps = []
misaligned_teeth = []
teeth_labels = {1: [], 2: []}

for arch_id, dlist in arches.items():
    d_sorted = sorted(dlist, key=lambda d: d["cx"])

    # Label teeth
    for idx, d in enumerate(d_sorted):
        tooth_label = f"T{idx+1}"
        teeth_labels[arch_id + 1].append(tooth_label)
        x, y = int(d["bx_min"]), int(d["cy"])

        cv2.putText(annot, tooth_label, (x, y),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.5, COLOR_LABEL, 1)

    # Compute gaps
    for i in range(len(d_sorted) - 1):
        gap = d_sorted[i + 1]["bx_min"] - d_sorted[i]["bx_max"]
        if gap < 0:
            gap = 0

        if gap > GAP_ALERT_PX:
            mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i + 1]["bx_min"]) / 2)
            mid_y = int((d_sorted[i]["cy"] + d_sorted[i + 1]["cy"]) / 2)

            cv2.putText(annot, f"{gap:.0f}px", (mid_x, mid_y),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.5, COLOR_GAP, 2)

            important_gaps.append({
                "arch": arch_id + 1,
                "left_tooth": i + 1,
                "right_tooth": i + 2,
                "gap_px": gap
            })

# =========================================
# ALIGNMENT CHECK
# =========================================
align_std = np.std([d["cy"] for d in detections])
alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Misaligned"

if alignment == "Misaligned":
    misaligned_teeth = teeth_labels[1] + teeth_labels[2]  # Mark all for simplicity

# =========================================
# DISPLAY IMAGE
# =========================================
plt.figure(figsize=(8, 5))
plt.imshow(cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
plt.title("Teeth with Gaps & Alignment Check")
plt.axis('off')
plt.show()

# =========================================
# PRINT RESULTS
# =========================================
print("=== Teeth Identified ===")
print(f"Upper Arch: {', '.join(teeth_labels[1])}")
print(f"Lower Arch: {', '.join(teeth_labels[2])}")

print("\n=== Significant Gaps ===")
if important_gaps:
    for g in important_gaps:
        print(f"Arch {g['arch']} → Gap between T{g['left_tooth']} & T{g['right_tooth']}: {g['gap_px']:.0f}px")
else:
    print("No significant gaps detected.")

print("\n=== Alignment Status ===")
print(f"Alignment: {alignment}")
if alignment == "Misaligned":
    print("Teeth requiring caps (due to misalignment):", ", ".join(misaligned_teeth))

print("\n=== Crown Type Suggestions ===")
print("- Metal Crowns")
print("- Porcelain-Fused-to-Metal (PFM) Crowns")
print("- All-Ceramic or Porcelain Crowns")
print("- Zirconia Crowns")
print("- Composite Resin Crowns")
print("- Temporary Crowns (until permanent crown is ready)")

