import os
import cv2
import numpy as np
import json
from shapely.geometry import Polygon
from sklearn.cluster import KMeans
from jinja2 import Environment, FileSystemLoader, select_autoescape
import pdfkit
import tempfile
import base64
from inference_sdk import InferenceHTTPClient
from google.colab import files
from IPython.display import Image, display

# --- Configuration ---
API_KEY = "DFlrjZHolOe8aC38zXZS"              # REPLACE WITH YOUR KEY
MODEL_ID = "dentalmate/3"                     # REPLACE WITH YOUR MODEL ID (e.g., "workspace/project/version")
API_URL = "https://serverless.roboflow.com"   # Serverless endpoint

# Analysis thresholds
MIN_BOX_WH = 10                               # Min tooth detection size (px)
GAP_ALERT_PX = 15                             # Min gap size to annotate (px)
ALIGN_ALERT_PX = 25                           # Max alignment stddev (px) for "normal"
CONFIDENCE = 30                               # YOUR CONFIDENCE FILTER (%)

# Reference tooth for pixel-to-mm calibration (optional)
KNOWN_MM_PER_TOOTH = 8.5
USE_REF_TOOTH_IDX = 0

# Colors (BGR)
COLOR_LABEL = (0, 255, 0)                     # Green: tooth labels
COLOR_GAP = (255, 0, 0)                       # Blue: gap labels
COLOR_ARCH = [(255, 0, 255), (0, 255, 255)]   # Magenta/Cyan: upper/lower arches

# Report info
REPORT_TITLE = "Dental AI Analysis Report"
PATIENT_ID = "P-12345"

# Cave-in detection
CAVEIN_AREA_RATIO = 0.5
CAVEIN_CONCAVITY_THRESH = 0.2

# --- Helper Functions ---
def image_to_base64(image_path):
    with open(image_path, "rb") as f:
        return base64.b64encode(f.read()).decode("utf-8")

def compute_concavity(polygon):
    convex_hull = polygon.convex_hull
    if not convex_hull.is_valid or convex_hull.area <= 0:
        return 0.0
    area = polygon.area
    ch_area = convex_hull.area
    return max(0.0, (ch_area - area) / ch_area)

# --- Main Analysis ---
def main(image_path):
    client = InferenceHTTPClient(api_url=API_URL, api_key=API_KEY)

    # 1. Debug: Show uploaded image
    print("\n--- Uploaded Image Preview ---")
    display(Image(filename=image_path))
    img_cv = cv2.imread(image_path)
    if img_cv is None:
        raise RuntimeError(f"Could not read image: {image_path}")
    print(f"Image size: {img_cv.shape} (HxWxC)")

    # 2. Run inference (NO confidence parameter on infer())
    result = client.infer(image_path, model_id=MODEL_ID)
    print("\n--- Raw API Output (first 500 chars) ---")
    print(json.dumps(result, indent=2)[:500] + "..." if len(json.dumps(result)) > 500 else json.dumps(result, indent=2))

    if "predictions" not in result:
        raise ValueError("API response missing 'predictions' key. Check API and model.")

    predictions = result["predictions"]
    if not predictions:
        raise ValueError(
            "No predictions found in API response.\n"
            "Possible causes:\n"
            " - Your image does not contain clearly visible teeth (check preview above).\n"
            " - The model is not trained for your image type (photo/X-ray, etc.).\n"
            " - You are using the wrong MODEL_ID or API_KEY.\n"
            " - Try a clearer, frontal, high-contrast dental image."
        )

    # 3. Filter by YOUR confidence threshold (post-processing)
    filtered_predictions = [p for p in predictions if p.get("confidence", 0) >= CONFIDENCE / 100]
    if not filtered_predictions:
        raise ValueError(
            f"No predictions with confidence ≥ {CONFIDENCE}%.\n"
            f"Found {len(predictions)} predictions total. Try lowering CONFIDENCE."
        )

    print(f"\n--- Detections Found ---\nTotal: {len(predictions)}, After Filter: {len(filtered_predictions)}")

    # 4. Parse detections
    detections = []
    for p in filtered_predictions:
        x, y, w, h = p["x"], p["y"], p["width"], p["height"]
        if w < MIN_BOX_WH or h < MIN_BOX_WH:
            continue

        x_min, x_max = x - w/2, x + w/2
        y_min, y_max = y - h/2, y + h/2
        pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)
        poly = Polygon(pts)
        if not poly.is_valid or poly.area <= 0:
            continue

        bx_min, by_min, bx_max, by_max = poly.bounds
        cx, cy = (bx_min + bx_max)/2, (by_min + by_max)/2
        w_px, h_px, area_px = bx_max - bx_min, by_max - by_min, poly.area

        detections.append({
            "class": p.get("class", "tooth"),
            "conf": p.get("confidence", 1.0),
            "pts": pts.astype(int),
            "poly": poly,
            "cx": cx, "cy": cy,
            "bx_min": bx_min, "bx_max": bx_max,
            "by_min": by_min, "by_max": by_max,
            "w_px": w_px, "h_px": h_px,
            "area_px": area_px,
        })

    if not detections:
        raise ValueError(
            "No detections passed all filters (size, validity, etc.).\n"
            "Try a clearer image, lower CONFIDENCE, or check your model."
        )

    # 5. Cluster teeth into arches (by y-coordinate)
    y_coords = np.array([[d["cy"]] for d in detections])
    n_clusters = 2 if len(detections) >= 6 else 1
    if len(detections) >= 2:
        km = KMeans(n_clusters=n_clusters, n_init=5, random_state=0)
        labels = km.fit_predict(y_coords)
    else:
        labels = np.zeros(len(detections))

    arch_map = {}
    for d, lab in zip(detections, labels):
        arch_map.setdefault(lab, []).append(d)
    label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
    arches = {arch_id+1: arch_map[old_id] for arch_id, old_id in enumerate(label_order)}

    # 6. Annotate image
    annot = img_cv.copy()
    teeth_rows = []
    gap_rows = []
    cavein_rows = []
    px_per_mm = None

    # Pixel-to-mm calibration using reference tooth (optional)
    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        if len(d_sorted) > USE_REF_TOOTH_IDX:
            ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
            if ref_w_px > 0:
                px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH
            break

    # 7. Process arches and teeth
    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        col = COLOR_ARCH[(arch_id-1) % len(COLOR_ARCH)]

        for idx, d in enumerate(d_sorted):
            cv2.polylines(annot, [d["pts"]], True, col, 2)
            label = f"A{arch_id}T{idx+1}"
            cv2.putText(annot, label, (int(d["bx_min"]), max(0, int(d["by_min"])-5)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.4, col, 1, cv2.LINE_AA)

            ch = d["poly"].convex_hull
            area_ratio = d["area_px"] / ch.area if ch.area > 0 else 1.0
            concavity = compute_concavity(d["poly"])
            is_cavein = (area_ratio < CAVEIN_AREA_RATIO) or (concavity > CAVEIN_CONCAVITY_THRESH)
            treatment = "N/A"
            timeline = "N/A"
            if is_cavein:
                cv2.putText(annot, "Cave-in", (int(d["cx"]), int(d["cy"])),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 0, 255), 1, cv2.LINE_AA)
                treatment = "Restoration (filling or buildup)" if area_ratio > 0.3 else "Endodontic + Crown or Extraction"
                timeline = "1–2 visits (2–4 weeks)" if area_ratio > 0.3 else "3–6 visits (4–12 weeks)"
                cavein_rows.append({
                    "arch": arch_id,
                    "tooth": idx+1,
                    "area_ratio": f"{area_ratio:.2f}",
                    "concavity": f"{concavity:.2f}",
                    "treatment": treatment,
                    "timeline": timeline,
                })

            teeth_rows.append({
                "arch": arch_id,
                "tooth": idx+1,
                "class": d["class"],
                "confidence": f"{d['conf']:.2f}",
                "cx_px": f"{d['cx']:.1f}",
                "cy_px": f"{d['cy']:.1f}",
                "width_px": f"{d['w_px']:.1f}",
                "width_mm": f"{d['w_px'] / px_per_mm:.1f}" if px_per_mm else "—",
                "height_px": f"{d['h_px']:.1f}",
                "area_px": f"{d['area_px']:.1f}",
                "is_cavein": "Yes" if is_cavein else "No",
                "cavein_treatment": treatment,
                "cavein_timeline": timeline,
            })

        # Gap analysis
        for i in range(len(d_sorted)-1):
            gap_px = max(0, d_sorted[i+1]["bx_min"] - d_sorted[i]["bx_max"])
            gap_mm = gap_px / px_per_mm if px_per_mm else None

            if gap_px > GAP_ALERT_PX:
                mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i+1]["bx_min"]) / 2)
                mid_y = int((d_sorted[i]["cy"] + d_sorted[i+1]["cy"]) / 2)
                cv2.putText(annot, f"{gap_px:.0f}px", (mid_x, mid_y),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, COLOR_GAP, 1, cv2.LINE_AA)

                if gap_px < 25:
                    cap_type = "Composite Resin Crown, Zirconia Crown, or PFM Crown"
                    timeline = "2–3 weeks"
                elif gap_px < 50:
                    cap_type = "Zirconia or Porcelain-Fused-to-Metal Bridge"
                    timeline = "3–6 weeks"
                else:
                    cap_type = "Multi-unit Bridge or Orthodontic Alignment + Prosthetics"
                    timeline = "6–12+ weeks"

                gap_rows.append({
                    "arch": arch_id,
                    "left_tooth": i+1,
                    "right_tooth": i+2,
                    "gap_px": f"{gap_px:.1f}",
                    "gap_mm": f"{gap_mm:.1f}" if gap_mm else "—",
                    "cap_type": cap_type,
                    "timeline": timeline,
                })

    # 8. Alignment check
    all_cx = np.array([d["cx"] for d in detections])
    align_std = np.std(all_cx)
    alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted (Misaligned)"
    misaligned_teeth = [f"A{row['arch']}T{row['tooth']}" for row in teeth_rows] if alignment == "Distracted (Misaligned)" else []

    # 9. Save annotated image for report
    with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as tmp_img:
        temp_path = tmp_img.name
        cv2.imwrite(temp_path, cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
    img_base64 = image_to_base64(temp_path)
    os.unlink(temp_path)

    # 10. HTML/PDF report
    report_context = {
        "title": REPORT_TITLE,
        "patient_id": PATIENT_ID,
        "image_base64": img_base64,
        "teeth_table": teeth_rows,
        "gaps_table": gap_rows,
        "caveins_table": cavein_rows,
        "alignment": alignment,
        "misaligned_teeth": ", ".join(misaligned_teeth) if misaligned_teeth else "None",
        "gap_alert_px": GAP_ALERT_PX,
        "align_alert_px": ALIGN_ALERT_PX,
        "cavein_area_ratio": CAVEIN_AREA_RATIO,
        "cavein_concavity": CAVEIN_CONCAVITY_THRESH,
    }

    html_template = r"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8"/>
    <meta name="viewport" content="width=device-width, initial-scale=1"/>
    <title>{{ title }}</title>
    <style>
        body { font-family: Arial, sans-serif; line-height: 1.6; margin: 20px; }
        h1 { color: #2c3e50; }
        h2 { color: #3498db; margin-top: 25px; }
        table { border-collapse: collapse; width: 100%; margin-bottom: 20px; font-size: 0.9em; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background: #f2f2f2; }
        .image-container { text-align: center; margin-bottom: 20px; }
        .image-container img { max-width: 100%; height: auto; border: 1px solid #ccc; }
        .summary { background-color: #f8f9fa; padding: 15px; border-radius: 5px; margin-bottom: 20px; }
        .alert { color: #c0392b; font-weight: bold; }
    </style>
</head>
<body>
    <h1>{{ title }}</h1>
    <p><strong>Patient ID:</strong> {{ patient_id }}</p>

    <div class="image-container">
        <img src="data:image/jpg;base64,{{ image_base64 }}" alt="Dental Analysis Visualization"/>
    </div>

    <div class="summary">
        <h2>Summary</h2>
        <p><strong>Alignment Status:</strong> {{ alignment }}</p>
        {% if misaligned_teeth != "None" %}
        <p><strong>Misaligned Teeth:</strong> {{ misaligned_teeth }}</p>
        {% endif %}
        {% if gaps_table %}
        <p><strong>Large Gaps Detected:</strong> Yes (see details below)</p>
        {% else %}
        <p><strong>Large Gaps Detected:</strong> No gaps above {{ gap_alert_px }} px threshold</p>
        {% endif %}
        {% if caveins_table %}
        <p><strong>Cave-in/Carious Teeth Detected:</strong> Yes (see details below)</p>
        {% else %}
        <p><strong>Cave-in/Carious Teeth Detected:</strong> No</p>
        {% endif %}
    </div>

    <h2>Tooth Analysis</h2>
    <table>
        <thead>
            <tr>
                <th>Arch</th><th>Tooth</th><th>Class</th><th>Confidence</th>
                <th>Width (px)</th><th>Width (mm)</th><th>Height (px)</th><th>Area (px)</th>
                <th>Cave-in?</th><th>Treatment</th><th>Timeline</th>
            </tr>
        </thead>
        <tbody>
            {% for row in teeth_table %}
            <tr>
                <td>{{ row.arch }}</td>
                <td>{{ row.tooth }}</td>
                <td>{{ row.class }}</td>
                <td>{{ row.confidence }}</td>
                <td>{{ row.width_px }}</td>
                <td>{{ row.width_mm }}</td>
                <td>{{ row.height_px }}</td>
                <td>{{ row.area_px }}</td>
                <td>{{ row.is_cavein }}</td>
                <td>{{ row.cavein_treatment }}</td>
                <td>{{ row.cavein_timeline }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    {% if gaps_table %}
    <h2>Gap Analysis & Cap Suggestions</h2>
    <table>
        <thead>
            <tr>
                <th>Arch</th><th>Left Tooth</th><th>Right Tooth</th>
                <th>Gap (px)</th><th>Gap (mm)</th><th>Cap Type</th><th>Timeline</th>
            </tr>
        </thead>
        <tbody>
            {% for row in gaps_table %}
            <tr>
                <td>{{ row.arch }}</td>
                <td>{{ row.left_tooth }}</td>
                <td>{{ row.right_tooth }}</td>
                <td>{{ row.gap_px }}</td>
                <td>{{ row.gap_mm }}</td>
                <td>{{ row.cap_type }}</td>
                <td>{{ row.timeline }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
    {% endif %}

    {% if caveins_table %}
    <h2>Cave-in/Carious Teeth & Restorative Recommendations</h2>
    <table>
        <thead>
            <tr>
                <th>Arch</th><th>Tooth</th><th>Area Ratio</th><th>Concavity</th><th>Treatment</th><th>Timeline</th>
            </tr>
        </thead>
        <tbody>
            {% for row in caveins_table %}
            <tr>
                <td>{{ row.arch }}</td>
                <td>{{ row.tooth }}</td>
                <td>{{ row.area_ratio }}</td>
                <td>{{ row.concavity }}</td>
                <td>{{ row.treatment }}</td>
                <td>{{ row.timeline }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
    {% endif %}

    <h2>Clinical Recommendations</h2>
    <ul>
        <li><strong>Cap Needed:</strong> Recommended for teeth with significant gaps, misalignment, or structural compromise.</li>
        <li><strong>Restorative Treatment:</strong> Required for caved-in/carious teeth to prevent progression and restore function.</li>
        <li><strong>Follow-Up:</strong> Review with a dental professional for definitive treatment planning and patient-specific considerations.</li>
        <li><strong>Estimated Timelines:</strong> Provided for common clinical scenarios; actual treatment may vary based on patient factors.</li>
    </ul>
</body>
</html>
"""

    env = Environment(loader=FileSystemLoader('.'), autoescape=select_autoescape(['html', 'xml']))
    template = env.from_string(html_template)
    html_report = template.render(**report_context)

    html_report_path = "dental_report.html"
    with open(html_report_path, "w") as f:
        f.write(html_report)
    print(f"HTML report saved to {html_report_path}")

    pdf_report_path = "dental_report.pdf"
    pdfkit.from_string(html_report, pdf_report_path, options={"encoding": "UTF-8", "quiet": ""})
    print(f"PDF report saved to {pdf_report_path}")

    try:
        files.download(pdf_report_path)
    except Exception as e:
        print("Could not auto-download PDF in Colab. Check the file browser.")

    return html_report_path, pdf_report_path

if __name__ == "__main__":
    print("--- Dental Analysis ---\nUpload your image:")
    uploaded = files.upload()
    if not uploaded:
        raise RuntimeError("No image uploaded.")
    image_path = list(uploaded.keys())[0]
    main(image_path)

import os
import cv2
import numpy as np
from shapely.geometry import Polygon
from sklearn.cluster import KMeans
from jinja2 import Environment, FileSystemLoader, select_autoescape
import pdfkit
import tempfile
import base64
from roboflow import Roboflow
from google.colab import files

# --- Configuration ---

API_KEY = "DFlrjZHolOe8aC38zXZS"              # Replace with your API key
WORKSPACE = "ranjita-infb1"
PROJECT = "cavity-detection-pe9t4"
VERSION = 1

CONFIDENCE = 40                               # confidence threshold (%)
MIN_BOX_WH = 10                               # minimum detection size (px)
GAP_ALERT_PX = 15                             # gap alert threshold (px)
ALIGN_ALERT_PX = 25                           # alignment threshold (px, std dev)

KNOWN_MM_PER_TOOTH = 8.5                      # average incisor width (mm)
USE_REF_TOOTH_IDX = 0                         # reference tooth for scaling

COLOR_LABEL = (0, 255, 0)                     # Green: tooth label
COLOR_GAP = (255, 0, 0)                       # Blue: gap label
COLOR_ARCH = [(255, 0, 255), (0, 255, 255)]   # Magenta/Cyan: arch labels

REPORT_TITLE = "Dental AI Analysis Report"
PATIENT_ID = "P-12345"

CAVEIN_AREA_RATIO = 0.5                       # area ratio threshold
CAVEIN_CONCAVITY_THRESH = 0.2                 # concavity ratio threshold

# --- Helper Functions ---

def image_to_base64(image_path):
    """Convert image to base64 string for HTML embedding."""
    with open(image_path, "rb") as img_file:
        return base64.b64encode(img_file.read()).decode("utf-8")

def ndarray_to_base64(img):
    """Convert numpy array (image) to base64 string."""
    _, buffer = cv2.imencode('.png', img)
    return base64.b64encode(buffer).decode("utf-8")

def compute_concavity(polygon):
    """Compute concavity ratio of a polygon."""
    convex_hull = polygon.convex_hull
    if not convex_hull.is_valid or convex_hull.area <= 0:
        return 0.0
    area = polygon.area
    ch_area = convex_hull.area
    return max(0.0, (ch_area - area) / ch_area)

def process_image_variants(img):
    """Generate all processed variants of the image."""
    grayscale = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    hist_eq = cv2.equalizeHist(grayscale)
    _, binary = cv2.threshold(hist_eq, 127, 255, cv2.THRESH_BINARY)
    kernel = np.ones((5, 5), np.uint8)
    erosion = cv2.erode(binary, kernel, iterations=1)
    dilation = cv2.dilate(binary, kernel, iterations=1)
    opening = cv2.morphologyEx(binary, cv2.MORPH_OPEN, kernel)
    closing = cv2.morphologyEx(binary, cv2.MORPH_CLOSE, kernel)
    return {
        "original": img,
        "grayscale": grayscale,
        "histogram_equalized": hist_eq,
        "binary": binary,
        "erosion": erosion,
        "dilation": dilation,
        "opening": opening,
        "closing": closing,
    }

# --- Main Analysis Function ---

def main(image_path):
    # Initialize Roboflow model
    rf = Roboflow(api_key=API_KEY)
    project = rf.workspace(WORKSPACE).project(PROJECT)
    model = project.version(VERSION).model

    # Predict with confidence threshold
    pred_json = model.predict(image_path, confidence=CONFIDENCE).json()

    # Load image for annotation & processing
    img = cv2.imread(image_path)
    if img is None:
        raise RuntimeError(f"Could not read image: {image_path}")
    H, W = img.shape[:2]

    # --- Image Processing Variants ---
    img_variants = process_image_variants(img)

    # --- Parse predictions ---
    detections = []
    for p in pred_json["predictions"]:
        w = p.get("width", 0)
        h = p.get("height", 0)
        if w < MIN_BOX_WH or h < MIN_BOX_WH:
            continue
        if "points" in p and p["points"]:
            pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
        else:
            x, y = p["x"], p["y"]
            x_min, x_max = x - w/2, x + w/2
            y_min, y_max = y - h/2, y + h/2
            pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)
        poly = Polygon(pts)
        if not poly.is_valid or poly.area <= 0:
            continue
        bx_min, by_min, bx_max, by_max = poly.bounds
        cx, cy = (bx_min + bx_max)/2, (by_min + by_max)/2
        w_px, h_px, area_px = bx_max - bx_min, by_max - by_min, poly.area
        detections.append({
            "class": p.get("class", "tooth"),
            "conf": p.get("confidence", 1.0),
            "pts": pts.astype(int),
            "poly": poly,
            "cx": cx, "cy": cy,
            "bx_min": bx_min, "bx_max": bx_max,
            "by_min": by_min, "by_max": by_max,
            "w_px": w_px, "h_px": h_px, "area_px": area_px,
        })

    if not detections:
        raise ValueError("No usable detections. Try lowering confidence or uploading a clearer image.")

    # --- Cluster into upper/lower arches ---
    y_coords = np.array([[d["cy"]] for d in detections])
    n_clusters = 2 if len(detections) >= 6 else 1
    if len(detections) >= 2:
        km = KMeans(n_clusters=n_clusters, n_init=5, random_state=0)
        labels = km.fit_predict(y_coords)
    else:
        labels = np.zeros(len(detections))
    arch_map = {}
    for d, lab in zip(detections, labels):
        arch_map.setdefault(lab, []).append(d)
    label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
    arches = {arch_id + 1: arch_map[old_id] for arch_id, old_id in enumerate(label_order)}

    # --- Analyze each arch ---
    annot = img.copy()
    teeth_rows = []
    gap_rows = []
    cavein_rows = []
    px_per_mm = None

    # Pixel-to-mm scale from reference tooth
    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        if len(d_sorted) > USE_REF_TOOTH_IDX:
            ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
            if ref_w_px > 0:
                px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH
            break

    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        col = COLOR_ARCH[(arch_id - 1) % len(COLOR_ARCH)]
        for idx, d in enumerate(d_sorted):
            cv2.polylines(annot, [d["pts"]], True, col, 2)
            label = f"A{arch_id}T{idx + 1}"
            cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.4, col, 1, cv2.LINE_AA)
            ch = d["poly"].convex_hull
            area_ratio = d["area_px"] / ch.area if ch.area > 0 else 1.0
            concavity = compute_concavity(d["poly"])
            is_cavein = (area_ratio < CAVEIN_AREA_RATIO) or (concavity > CAVEIN_CONCAVITY_THRESH)
            treatment = "N/A"
            timeline = "N/A"
            if is_cavein:
                cv2.putText(annot, "Cave-in", (int(d["cx"]), int(d["cy"])),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 0, 255), 1, cv2.LINE_AA)
                treatment = "Restoration (filling or buildup)" if area_ratio > 0.3 else "Endodontic + Crown or Extraction"
                timeline = "1–2 visits (2–4 weeks)" if area_ratio > 0.3 else "3–6 visits (4–12 weeks)"
                cavein_rows.append({
                    "arch": arch_id, "tooth": idx + 1,
                    "area_ratio": f"{area_ratio:.2f}",
                    "concavity": f"{concavity:.2f}",
                    "treatment": treatment, "timeline": timeline,
                })
            teeth_rows.append({
                "arch": arch_id, "tooth": idx + 1,
                "class": d["class"], "confidence": f"{d['conf']:.2f}",
                "cx_px": f"{d['cx']:.1f}", "cy_px": f"{d['cy']:.1f}",
                "width_px": f"{d['w_px']:.1f}",
                "width_mm": f"{d['w_px'] / px_per_mm:.1f}" if px_per_mm else "N/A",
                "height_px": f"{d['h_px']:.1f}",
                "area_px": f"{d['area_px']:.1f}",
                "is_cavein": "Yes" if is_cavein else "No",
                "cavein_treatment": treatment,
                "cavein_timeline": timeline,
            })
        for i in range(len(d_sorted) - 1):
            gap_px = max(0, d_sorted[i + 1]["bx_min"] - d_sorted[i]["bx_max"])
            gap_mm = gap_px / px_per_mm if px_per_mm else None
            if gap_px > GAP_ALERT_PX:
                mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i + 1]["bx_min"]) / 2)
                mid_y = int((d_sorted[i]["cy"] + d_sorted[i + 1]["cy"]) / 2)
                cv2.putText(annot, f"{gap_px:.0f}px", (mid_x, mid_y),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, COLOR_GAP, 1, cv2.LINE_AA)
                if gap_px < 25:
                    cap_type = "Composite Resin Crown, Zirconia Crown, or PFM Crown"
                    timeline = "2–3 weeks"
                elif gap_px < 50:
                    cap_type = "Zirconia or Porcelain-Fused-to-Metal Bridge"
                    timeline = "3–6 weeks"
                else:
                    cap_type = "Multi-unit Bridge or Orthodontic Alignment + Prosthetics"
                    timeline = "6–12+ weeks"
                gap_rows.append({
                    "arch": arch_id, "left_tooth": i + 1, "right_tooth": i + 2,
                    "gap_px": f"{gap_px:.1f}",
                    "gap_mm": f"{gap_mm:.1f}" if gap_mm else "N/A",
                    "cap_type": cap_type, "timeline": timeline,
                })

    # --- Alignment Check ---
    all_cx = np.array([d["cx"] for d in detections])
    align_std = np.std(all_cx)
    alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted (Misaligned)"
    if align_std >= ALIGN_ALERT_PX:
        misaligned_teeth = [f"A{row['arch']}T{row['tooth']}" for row in teeth_rows]
    else:
        misaligned_teeth = []

    # --- Embed all processed images in the report ---
    # Annotated image (original with boxes/annotations)
    with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as temp_img:
        temp_img_path = temp_img.name
        cv2.imwrite(temp_img_path, cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
    img_data = image_to_base64(temp_img_path)
    os.unlink(temp_img_path)

    # Create list of all processed image base64 strings and their captions
    process_variants = [
        {"name": "Original (Annotated)", "img": annot, "desc": "The raw input image after annotation."},
        {"name": "Original (Unannotated)", "img": img, "desc": "The raw input image before any processing."},
        {"name": "Grayscale", "img": img_variants["grayscale"], "desc": "Converts the image to shades of gray (single channel)."},
        {"name": "Histogram Equalized", "img": img_variants["histogram_equalized"], "desc": "Enhances contrast by spreading out pixel values."},
        {"name": "Binary Threshold", "img": img_variants["binary"], "desc": "Thresholds the image to black and white."},
        {"name": "Erosion", "img": img_variants["erosion"], "desc": "Erodes white regions (shrinks objects, removes noise)."},
        {"name": "Dilation", "img": img_variants["dilation"], "desc": "Dilates white regions (expands objects, fills gaps)."},
        {"name": "Opening", "img": img_variants["opening"], "desc": "Erosion followed by dilation (removes small noise)."},
        {"name": "Closing", "img": img_variants["closing"], "desc": "Dilation followed by erosion (fills small holes)."},
    ]
    variant_base64 = []
    for variant in process_variants:
        if len(variant["img"].shape) == 3:  # color
            _img = cv2.cvtColor(variant["img"], cv2.COLOR_BGR2RGB)
        else:  # grayscale
            _img = variant["img"]
        variant_base64.append({
            "name": variant["name"],
            "base64": ndarray_to_base64(_img),
            "desc": variant["desc"],
        })

    # --- HTML Report Template ---
    # Extended to show all image variants
    HTML_TEMPLATE = """
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8"/>
    <meta name="viewport" content="width=device-width, initial-scale=1"/>
    <title>{{ title }}</title>
    <style>
        body { font-family: Arial, sans-serif; line-height: 1.6; margin: 20px; }
        h1 { color: #2c3e50; }
        h2 { color: #3498db; margin-top: 25px; }
        table { border-collapse: collapse; width: 100%; margin-bottom: 20px; font-size: 0.9em; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background: #f2f2f2; }
        .image-container { text-align: center; margin: 20px 0; }
        .image-var { margin: 20px 0; }
        .image-gallery { display: flex; flex-wrap: wrap; gap: 20px; margin: 20px 0; }
        .image-gallery img { max-width: 100%; height: auto; border: 1px solid #ccc; }
        .image-desc { font-style: italic; color: #555; margin: 5px 0; }
        .summary { background-color: #f8f9fa; padding: 15px; border-radius: 5px; margin-bottom: 20px; }
        .alert { color: #c0392b; font-weight: bold; }
    </style>
</head>
<body>
    <h1>{{ title }}</h1>
    <p><strong>Patient ID:</strong> {{ patient_id }}</p>

    <div class="image-container">
        <h2>Image Processing Pipeline</h2>

        {% for img in image_variants %}
        <div class="image-var">
            <h3>{{ img.name }}</h3>
            <div class="image-gallery">
                <img src="data:image/png;base64,{{ img.base64 }}" alt="{{ img.name }}"/>
            </div>
            <p class="image-desc">{{ img.desc }}</p>
        </div>
        {% endfor %}
    </div>

    <div class="summary">
        <h2>Summary</h2>
        <p><strong>Alignment Status:</strong> {{ alignment }}</p>
        {% if misaligned_teeth != "None" %}
        <p><strong>Misaligned Teeth:</strong> {{ misaligned_teeth }}</p>
        {% endif %}
        {% if gaps_table %}
        <p><strong>Large Gaps Detected:</strong> Yes (see details below)</p>
        {% else %}
        <p><strong>Large Gaps Detected:</strong> No gaps above {{ gap_alert_px }} px threshold</p>
        {% endif %}
        {% if caveins_table %}
        <p><strong>Cave-in/Carious Teeth Detected:</strong> Yes (see details below)</p>
        {% else %}
        <p><strong>Cave-in/Carious Teeth Detected:</strong> No</p>
        {% endif %}
    </div>

    <h2>Tooth Analysis</h2>
    <table>
        <thead>
            <tr>
                <th>Arch</th><th>Tooth</th><th>Class</th><th>Confidence</th>
                <th>Width (px)</th><th>Width (mm)</th><th>Height (px)</th><th>Area (px)</th>
                <th>Cave-in?</th><th>Treatment</th><th>Timeline</th>
            </tr>
        </thead>
        <tbody>
            {% for row in teeth_table %}
            <tr>
                <td>{{ row.arch }}</td>
                <td>{{ row.tooth }}</td>
                <td>{{ row.class }}</td>
                <td>{{ row.confidence }}</td>
                <td>{{ row.width_px }}</td>
                <td>{{ row.width_mm }}</td>
                <td>{{ row.height_px }}</td>
                <td>{{ row.area_px }}</td>
                <td>{{ row.is_cavein }}</td>
                <td>{{ row.cavein_treatment }}</td>
                <td>{{ row.cavein_timeline }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    {% if gaps_table %}
    <h2>Gap Analysis & Cap Suggestions</h2>
    <table>
        <thead>
            <tr>
                <th>Arch</th><th>Left Tooth</th><th>Right Tooth</th><th>Gap (px)</th><th>Gap (mm)</th><th>Cap Type</th><th>Timeline</th>
            </tr>
        </thead>
        <tbody>
            {% for row in gaps_table %}
            <tr>
                <td>{{ row.arch }}</td>
                <td>{{ row.left_tooth }}</td>
                <td>{{ row.right_tooth }}</td>
                <td>{{ row.gap_px }}</td>
                <td>{{ row.gap_mm }}</td>
                <td>{{ row.cap_type }}</td>
                <td>{{ row.timeline }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
    {% endif %}

    {% if caveins_table %}
    <h2>Cave-in/Carious Teeth & Restorative Recommendations</h2>
    <table>
        <thead>
            <tr>
                <th>Arch</th><th>Tooth</th><th>Area Ratio</th><th>Concavity</th><th>Treatment</th><th>Timeline</th>
            </tr>
        </thead>
        <tbody>
            {% for row in caveins_table %}
            <tr>
                <td>{{ row.arch }}</td>
                <td>{{ row.tooth }}</td>
                <td>{{ row.area_ratio }}</td>
                <td>{{ row.concavity }}</td>
                <td>{{ row.treatment }}</td>
                <td>{{ row.timeline }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
    {% endif %}

    <h2>Clinical Recommendations</h2>
    <ul>
        <li><strong>Cap Needed:</strong> Recommended for teeth with significant gaps, misalignment, or structural compromise.</li>
        <li><strong>Restorative Treatment:</strong> Required for caved-in/carious teeth to prevent progression and restore function.</li>
        <li><strong>Follow-Up:</strong> Review with a dental professional for definitive treatment planning and patient-specific considerations.</li>
        <li><strong>Estimated Timelines:</strong> Provided for common clinical scenarios; actual treatment may vary based on patient factors.</li>
    </ul>
</body>
</html>
"""

    # --- Render HTML Report ---
    env = Environment(loader=FileSystemLoader('.'), autoescape=select_autoescape(['html', 'xml']))
    template = env.from_string(HTML_TEMPLATE)
    html_report = template.render(
        title=REPORT_TITLE,
        patient_id=PATIENT_ID,
        image_base64=img_data,
        image_variants=variant_base64,
        teeth_table=teeth_rows,
        gaps_table=gap_rows,
        caveins_table=cavein_rows,
        alignment=alignment,
        misaligned_teeth=", ".join(misaligned_teeth) if misaligned_teeth else "None",
        gap_alert_px=GAP_ALERT_PX,
        align_alert_px=ALIGN_ALERT_PX,
        cavein_area_ratio=CAVEIN_AREA_RATIO,
        cavein_concavity=CAVEIN_CONCAVITY_THRESH,
    )

    # Save HTML report
    html_path = "dental_report.html"
    with open(html_path, "w") as f:
        f.write(html_report)
    print(f"\nHTML report saved to {html_path}")

    # --- Generate PDF Report (requires wkhtmltopdf) ---
    pdf_options = {
        "encoding": "UTF-8",
        "no-outline": None,
        "quiet": "",
    }
    pdf_path = "dental_report.pdf"
    pdfkit.from_string(html_report, pdf_path, options=pdf_options)
    print(f"PDF report saved to {pdf_path}")

    return html_path, pdf_path

# --- Runtime Logic ---
