API_KEY         = "DFlrjZHolOe8aC38zXZS"  # Replace with your key
WORKSPACE       = "ranjita-infb1"
PROJECT         = "cavity-detection-pe9t4"
VERSION         = 1
CONFIDENCE      = 40
MIN_BOX_WH      = 10
GAP_ALERT_PX    = 15
ALIGN_ALERT_PX  = 25

# Pixel→mm calibration
KNOWN_MM_PER_TOOTH = 8.5     # Average width of central incisor
USE_REF_TOOTH_IDX  = 0

# Colors
COLOR_LABEL  = (0, 255, 0)
COLOR_GAP    = (255, 0, 0)
COLOR_ARCH   = [(255,0,255), (0,255,255)]

# Scientific standard values (mm)
SCIENTIFIC_STANDARDS = {
    "overjet": (2, 3),
    "overbite": (2, 3),
    "midline_shift": 2,
    "curve_of_spee": (1, 2),
    "intercanine_width_maxilla": (26, 28),
    "intermolar_width_maxilla": (36, 38),
    "intercanine_width_mandible": (22, 24),
    "intermolar_width_mandible": (32, 34),
    "tooth_width_central_incisor_upper": (8.5, 9),
    "tooth_width_central_incisor_lower": (5, 6)
}

# ========================
