CONFIDENCE = 40        # Confidence threshold for detection
MIN_BOX_WH = 10        # Minimum bounding box size (px)
GAP_ALERT_PX = 15      # Gap threshold (px)
ALIGN_ALERT_PX = 25    # Alignment threshold (px)

KNOWN_MM_PER_TOOTH = 8.5   # Average incisor width (mm) for scaling
USE_REF_TOOTH_IDX = 0      # Reference tooth index for scaling

COLOR_LABEL = (0, 255, 0)        # Green for tooth label
COLOR_GAP = (255, 0, 0)          # Blue for gaps
COLOR_ARCH = [(255, 0, 255), (0, 255, 255)]  # Magenta / Cyan for arches

REPORT_TITLE = "Dental AI Analysis Report"
PATIENT_ID = "P-12345"

CAVEIN_AREA_RATIO = 0.5
