import os
import cv2
import numpy as np
import warnings
from scipy.optimize import curve_fit
from shapely.geometry import Polygon
from sklearn.cluster import KMeans
from jinja2 import Environment, FileSystemLoader, select_autoescape
import pdfkit
import tempfile
import base64
from roboflow import Roboflow
from google.colab import files

# ==========================
# CONFIGURATION
# ==========================
API_KEY = os.getenv('ROBOFLOW_API_KEY', 'DFlrjZHolOe8aC38zXZS')  # Replace or set env var
WORKSPACE = "ranjita-infb1"
PROJECT = "cavity-detection-pe9t4"
VERSION = 1

CONFIDENCE = 40        # Confidence threshold for detection
MIN_BOX_WH = 10        # Minimum bounding box size (px)
GAP_ALERT_PX = 15      # Gap threshold (px)
ALIGN_ALERT_PX = 25    # Alignment threshold (px)

KNOWN_MM_PER_TOOTH = 8.5   # Average incisor width (mm) for scaling
USE_REF_TOOTH_IDX = 0      # Reference tooth index for scaling

COLOR_LABEL = (0, 255, 0)        # Green for tooth label
COLOR_GAP = (255, 0, 0)          # Blue for gaps
COLOR_ARCH = [(255, 0, 255), (0, 255, 255)]  # Magenta / Cyan for arches

REPORT_TITLE = "Dental AI Analysis Report"
PATIENT_ID = "P-12345"

CAVEIN_AREA_RATIO = 0.5
CAVEIN_CONCAVITY_THRESH = 0.2

# ==========================
# HELPER FUNCTIONS
# ==========================

def image_to_base64(image_path):
    with open(image_path, "rb") as img_file:
        return base64.b64encode(img_file.read()).decode("utf-8")

def ndarray_to_base64(img):
    _, buffer = cv2.imencode('.png', img)
    return base64.b64encode(buffer).decode("utf-8")

def compute_concavity(polygon):
    if not polygon.is_valid or polygon.area <= 0:
        return 0.0
    convex_hull = polygon.convex_hull
    if not convex_hull.is_valid or convex_hull.area <= 0:
        return 0.0
    area = polygon.area
    ch_area = convex_hull.area
    return max(0.0, (ch_area - area) / ch_area)

def fit_arch_curve(x, y):
    if len(x) < 3:
        return np.full_like(y, np.nan)  # Too few points for quadratic fit
    def quadratic(x, a, b, c):
        return a * x**2 + b * x + c
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", category=RuntimeWarning)
            params, _ = curve_fit(quadratic, x, y)
            return quadratic(x, *params)
    except (RuntimeError, TypeError):
        return np.full_like(y, np.nan)

def midline_deviation(all_cx, image_width):
    if len(all_cx) == 0 or image_width == 0:
        return 0.0
    actual_midline = np.mean(all_cx)
    image_midline = image_width / 2
    return (actual_midline - image_midline) / image_width

def intertooth_angles(x_coords, y_coords):
    if len(x_coords) < 2:
        return np.array([])
    dx = np.diff(x_coords)
    dy = np.diff(y_coords)
    return np.degrees(np.arctan2(dy, dx))

def tooth_rotation_angle(polygon):
    try:
        rect = polygon.minimum_rotated_rectangle
        coords = np.array(rect.exterior.coords)
        v1 = coords[1] - coords[0]
        return np.degrees(np.arctan2(v1[1], v1[0]))
    except:
        return np.nan

def crowding_index(tooth_centers_x, arch_length):
    if len(tooth_centers_x) < 2 or arch_length <= 0:
        return 0.0
    span = max(tooth_centers_x) - min(tooth_centers_x)
    return span / arch_length

def analyze_arch_tooth_stats(dlist, image_width):
    x = np.array([d["cx"] for d in dlist])
    y = np.array([d["cy"] for d in dlist])
    if len(x) == 0:
        return {
            "num_teeth": 0,
            "arch_length_px": 0.0,
            "arch_rmse": np.nan,
            "midline_deviation_pct": 0.0,
            "crowding_index": 0.0,
            "avg_intertooth_angle": np.nan,
            "rotation_angles": []
        }
    arch_curve = fit_arch_curve(x, y)
    rmse = np.nan if np.all(np.isnan(arch_curve)) else np.sqrt(np.mean((y - arch_curve)**2))
    midline_dev = midline_deviation(x, image_width)
    angles = intertooth_angles(x, y)
    crowding = crowding_index(x, image_width)
    rotations = [tooth_rotation_angle(d["poly"]) for d in dlist]
    return {
        "num_teeth": len(dlist),
        "arch_length_px": max(x) - min(x),
        "arch_rmse": rmse,
        "midline_deviation_pct": midline_dev * 100,
        "crowding_index": crowding,
        "avg_intertooth_angle": np.mean(angles) if len(angles) > 0 else np.nan,
        "rotation_angles": rotations,
    }

# ==========================
# MAIN ANALYSIS FUNCTION
# ==========================

def main(image_path):
    # Initialize Roboflow model
    rf = Roboflow(api_key=API_KEY)
    project = rf.workspace(WORKSPACE).project(PROJECT)
    model = project.version(VERSION).model

    # Predict and load image
    pred_json = model.predict(image_path, confidence=CONFIDENCE).json()
    img = cv2.imread(image_path)
    if img is None:
        raise RuntimeError(f"Could not read image: {image_path}")
    H, W = img.shape[:2]

    # Parse detections
    detections = []
    for p in pred_json["predictions"]:
        w = p.get("width", 0)
        h = p.get("height", 0)
        if w < MIN_BOX_WH or h < MIN_BOX_WH:
            continue
        if "points" in p and p["points"]:
            pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
        else:
            x, y = p["x"], p["y"]
            x_min, x_max = x - w/2, x + w/2
            y_min, y_max = y - h/2, y + h/2
            pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)
        poly = Polygon(pts)
        if not poly.is_valid or poly.area <= 0:
            continue
        bx_min, by_min, bx_max, by_max = poly.bounds
        cx, cy = (bx_min + bx_max)/2, (by_min + by_max)/2
        w_px, h_px, area_px = bx_max - bx_min, by_max - by_min, poly.area
        detections.append({
            "class": p.get("class", "tooth"),
            "conf": p.get("confidence", 1.0),
            "pts": pts.astype(int),
            "poly": poly,
            "cx": cx, "cy": cy,
            "bx_min": bx_min, "bx_max": bx_max,
            "by_min": by_min, "by_max": by_max,
            "w_px": w_px, "h_px": h_px, "area_px": area_px,
        })

    if not detections:
        raise ValueError("No usable detections. Try lowering confidence or uploading a clearer image.")

    # Cluster into arches
    y_coords = np.array([[d["cy"]] for d in detections])
    n_clusters = 2 if len(detections) >= 6 else 1
    if len(detections) >= 2:
        km = KMeans(n_clusters=n_clusters, n_init="auto", random_state=0)
        labels = km.fit_predict(y_coords)
    else:
        labels = np.zeros(len(detections))
    arch_map = {}
    for d, lab in zip(detections, labels):
        arch_map.setdefault(lab, []).append(d)
    label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
    arches = {arch_id + 1: arch_map[old_id] for arch_id, old_id in enumerate(label_order)}

    # Annotate and analyze
    annot = img.copy()
    teeth_rows = []
    gap_rows = []
    cavein_rows = []
    alignment_table = []
    px_per_mm = None

    # Pixel-to-mm scaling
    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        if len(d_sorted) > USE_REF_TOOTH_IDX:
            ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
            if ref_w_px > 0:
                px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH
            break

    # Tooth processing
    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        col = COLOR_ARCH[(arch_id - 1) % len(COLOR_ARCH)]
        arch_stats = analyze_arch_tooth_stats(d_sorted, W)
        alignment_table.append({
            "arch": arch_id,
            "num_teeth": arch_stats["num_teeth"],
            "arch_length_px": f"{arch_stats['arch_length_px']:.1f}",
            "arch_rmse": f"{arch_stats['arch_rmse']:.2f}" if not np.isnan(arch_stats['arch_rmse']) else "N/A",
            "midline_deviation_pct": f"{arch_stats['midline_deviation_pct']:.1f}",
            "crowding_index": f"{arch_stats['crowding_index']:.2f}",
            "avg_intertooth_angle": f"{arch_stats['avg_intertooth_angle']:.1f}" if not np.isnan(arch_stats['avg_intertooth_angle']) else "N/A",
            "rotation_angles": [f"{a:.1f}" if not np.isnan(a) else "N/A" for a in arch_stats["rotation_angles"]],
        })
        for idx, d in enumerate(d_sorted):
            cv2.polylines(annot, [d["pts"]], True, col, 2)
            label = f"A{arch_id}T{idx + 1}"
            cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.4, col, 1, cv2.LINE_AA)
            # Check cave-in
            ch = d["poly"].convex_hull
            area_ratio = d["area_px"] / ch.area if ch.area > 0 else 1.0
            concavity = compute_concavity(d["poly"])
            is_cavein = (area_ratio < CAVEIN_AREA_RATIO) or (concavity > CAVEIN_CONCAVITY_THRESH)
            treatment = "N/A"
            timeline = "N/A"
            if is_cavein:
                cv2.putText(annot, "Cave-in", (int(d["cx"]), int(d["cy"])),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 0, 255), 1, cv2.LINE_AA)
                treatment = "Restoration (filling)" if area_ratio > 0.3 else "Endodontic + Crown or Extraction"
                timeline = "1–2 visits" if area_ratio > 0.3 else "3–6 visits"
                cavein_rows.append({
                    "arch": arch_id, "tooth": idx + 1,
                    "area_ratio": f"{area_ratio:.2f}",
                    "concavity": f"{concavity:.2f}",
                    "treatment": treatment, "timeline": timeline,
                })
            # Add to table
            teeth_rows.append({
                "arch": arch_id, "tooth": idx + 1,
                "class": d["class"], "confidence": f"{d['conf']:.2f}",
                "width_px": f"{d['w_px']:.1f}",
                "width_mm": f"{d['w_px'] / px_per_mm:.1f}" if px_per_mm else "N/A",
                "height_px": f"{d['h_px']:.1f}",
                "area_px": f"{d['area_px']:.1f}",
                "is_cavein": "Yes" if is_cavein else "No",
                "cavein_treatment": treatment,
                "cavein_timeline": timeline,
            })

        # Gap analysis
        for i in range(len(d_sorted) - 1):
            gap_px = max(0, d_sorted[i + 1]["bx_min"] - d_sorted[i]["bx_max"])
            gap_mm = gap_px / px_per_mm if px_per_mm else None
            if gap_px > GAP_ALERT_PX:
                mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i + 1]["bx_min"]) / 2)
                mid_y = int((d_sorted[i]["cy"] + d_sorted[i + 1]["cy"]) / 2)
                cv2.putText(annot, f"{gap_px:.0f}px", (mid_x, mid_y),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, COLOR_GAP, 1, cv2.LINE_AA)
                gap_rows.append({
                    "arch": arch_id,
                    "left_tooth": i + 1,
                    "right_tooth": i + 2,
                    "gap_px": f"{gap_px:.1f}",
                    "gap_mm": f"{gap_mm:.1f}" if gap_mm else "N/A",
                    "cap_type": "Composite/Zirconia/Bridge",
                    "timeline": "2–6 weeks",
                })

    # Overall alignment analysis
    all_cx = np.array([d["cx"] for d in detections])
    align_std = np.std(all_cx) if len(all_cx) > 0 else 0
    alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted (Misaligned)"
    misaligned_teeth = [f"A{row['arch']}T{row['tooth']}" for row in teeth_rows] if align_std >= ALIGN_ALERT_PX else []

    # Annotated image to base64
    with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as temp_img:
        temp_img_path = temp_img.name
        cv2.imwrite(temp_img_path, cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
    img_data = image_to_base64(temp_img_path)
    os.unlink(temp_img_path)

    # Prepare image for report
    variant_base64 = [
        {"name": "Original (Annotated)", "base64": img_data, "desc": "Input image with annotations"},
        {"name": "Original (Unannotated)", "base64": ndarray_to_base64(cv2.cvtColor(img, cv2.COLOR_BGR2RGB)), "desc": "Raw input image"},
    ]

    # Render HTML report
    HTML_TEMPLATE = """
<!DOCTYPE html>
<html>
<head>
    <title>{{ title }}</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        h1 { color: #0066cc; }
        h2 { color: #333366; }
        table { border-collapse: collapse; width: 100%; margin: 10px 0; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background-color: #f2f2f2; }
        .image-container { margin: 10px 0; }
        .image-container img { max-width: 600px; height: auto; }
    </style>
</head>
<body>
    <h1>{{ title }}</h1>
    <h2>Patient: {{ patient_id }}</h2>

    <h2>Annotated Image</h2>
    <div class="image-container">
        <img src="data:image/jpg;base64,{{ image_base64 }}" alt="Annotated Dental Image"/>
    </div>

    <h2>Detected Teeth & Cavities</h2>
    <table>
        <tr>
            <th>Arch</th><th>Tooth</th><th>Class</th><th>Confidence</th><th>Width (px)</th><th>Width (mm)</th>
            <th>Height (px)</th><th>Area (px)</th><th>Cavity Detected</th><th>Treatment</th><th>Timeline</th>
        </tr>
        {% for row in teeth_table %}
        <tr>
            <td>{{ row.arch }}</td><td>{{ row.tooth }}</td><td>{{ row.class }}</td>
            <td>{{ row.confidence }}</td><td>{{ row.width_px }}</td><td>{{ row.width_mm }}</td>
            <td>{{ row.height_px }}</td><td>{{ row.area_px }}</td><td>{{ row.is_cavein }}</td>
            <td>{{ row.cavein_treatment }}</td><td>{{ row.cavein_timeline }}</td>
        </tr>
        {% endfor %}
    </table>

    <h2>Gaps Analysis</h2>
    <table>
        <tr>
            <th>Arch</th><th>Left Tooth</th><th>Right Tooth</th><th>Gap (px)</th><th>Gap (mm)</th>
            <th>Cap Type</th><th>Timeline</th>
        </tr>
        {% for row in gaps_table %}
        <tr>
            <td>{{ row.arch }}</td><td>{{ row.left_tooth }}</td><td>{{ row.right_tooth }}</td>
            <td>{{ row.gap_px }}</td><td>{{ row.gap_mm }}</td>
            <td>{{ row.cap_type }}</td><td>{{ row.timeline }}</td>
        </tr>
        {% endfor %}
    </table>

    <h2>Cavities (Cave-Ins)</h2>
    <table>
        <tr>
            <th>Arch</th><th>Tooth</th><th>Area Ratio</th><th>Concavity</th><th>Treatment</th><th>Timeline</th>
        </tr>
        {% for row in caveins_table %}
        <tr>
            <td>{{ row.arch }}</td><td>{{ row.tooth }}</td><td>{{ row.area_ratio }}</td>
            <td>{{ row.concavity }}</td><td>{{ row.treatment }}</td><td>{{ row.timeline }}</td>
        </tr>
        {% endfor %}
    </table>

    <h2>Alignment Analysis</h2>
    <h3>Arch Metrics</h3>
    <table>
        <tr>
            <th>Arch</th><th>Num Teeth</th><th>Arch Length (px)</th><th>Arch RMSE</th><th>Midline Dev (%)</th>
            <th>Crowding Index</th><th>Avg Angle (deg)</th><th>Rotation Angles</th>
        </tr>
        {% for row in alignment_table %}
        <tr>
            <td>{{ row.arch }}</td><td>{{ row.num_teeth }}</td><td>{{ row.arch_length_px }}</td>
            <td>{{ row.arch_rmse }}</td><td>{{ row.midline_deviation_pct }}</td>
            <td>{{ row.crowding_index }}</td>
            <td>{{ row.avg_intertooth_angle }}</td>
            <td>{{ row.rotation_angles }}</td>
        </tr>
        {% endfor %}
    </table>

    <h3>Overall Alignment</h3>
    <p>Overall Alignment: <strong>{{ alignment }}</strong></p>
    {% if misaligned_teeth %}
    <p>Potential misaligned teeth: {{ misaligned_teeth }}</p>
    {% endif %}
    <p><em>Gap Alert Threshold: {{ gap_alert_px }}px | Alignment Alert Threshold: {{ align_alert_px }}px</em></p>
    <p><em>Cave-in Area Threshold: {{ cavein_area_ratio }} | Cave-in Concavity Threshold: {{ cavein_concavity_thresh }}</em></p>

    <p>Automatic analysis may have false positives/negatives. Always consult a dental professional.</p>
</body>
</html>
    """

    env = Environment(loader=FileSystemLoader('.'), autoescape=select_autoescape(['html', 'xml']))
    template = env.from_string(HTML_TEMPLATE)
    html_report = template.render(
        title=REPORT_TITLE,
        patient_id=PATIENT_ID,
        image_base64=img_data,
        image_variants=variant_base64,
        teeth_table=teeth_rows,
        gaps_table=gap_rows,
        caveins_table=cavein_rows,
        alignment=alignment,
        misaligned_teeth=", ".join(misaligned_teeth) if misaligned_teeth else "None",
        gap_alert_px=GAP_ALERT_PX,
        align_alert_px=ALIGN_ALERT_PX,
        cavein_area_ratio=CAVEIN_AREA_RATIO,
        cavein_concavity_thresh=CAVEIN_CONCAVITY_THRESH,
        alignment_table=alignment_table,
    )

    # Save HTML and PDF
    html_path = "alignment_report.html"
    with open(html_path, "w") as f:
        f.write(html_report)
    print(f"HTML report saved to {html_path}")

    pdf_path = "alignment_report.pdf"
    pdfkit.from_string(html_report, pdf_path, options={"encoding": "UTF-8"})
    print(f"PDF report saved to {pdf_path}")

    return html_path, pdf_path

