from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score
from roboflow import Roboflow

# --- Prediction Function ---
def predict_cavity(image_path):
    # Initialize Roboflow model
    rf = Roboflow(api_key=API_KEY)
    project = rf.workspace(WORKSPACE).project(PROJECT)
    model = project.version(VERSION).model

    # Get predictions
    pred_json = model.predict(image_path, confidence=CONFIDENCE).json()

    # Basic logic: if any prediction labeled "cavity"
    has_cavity = any(p.get("class", "").lower() == "cavity" for p in pred_json["predictions"])

    return "cavity" if has_cavity else "healthy"


# --- Evaluation Function ---
def evaluate_model(dataset):
    y_true = []
    y_pred = []

    for item in dataset:
        true_label = item["label"]
        pred_label = predict_cavity(item["image"])

        y_true.append(true_label)
        y_pred.append(pred_label)

    acc = accuracy_score(y_true, y_pred)
    prec = precision_score(y_true, y_pred, pos_label="cavity")
    rec = recall_score(y_true, y_pred, pos_label="cavity")
    f1 = f1_score(y_true, y_pred, pos_label="cavity")

    print(f"Accuracy: {acc:.2f}")
    print(f"Precision: {prec:.2f}")
    print(f"Recall: {rec:.2f}")
    print(f"F1-score: {f1:.2f}")


