import cv2
import numpy as np
import matplotlib.pyplot as plt

# -----------------------
# IMAGE PREPROCESSING FUNCTION
# -----------------------
def preprocess_image(image_path):
    """
    Step 2: Preprocessing - load and enhance the dental image
    """
    # Load image
    img = cv2.imread(image_path)

    # Convert to grayscale
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)

    # Histogram Equalization (contrast improvement)
    equalized = cv2.equalizeHist(gray)

    # Gaussian Blur (noise reduction)
    blurred = cv2.GaussianBlur(equalized, (5, 5), 0)

    # Show preprocessing steps
    fig, axes = plt.subplots(1, 3, figsize=(14, 5))
    steps = [("Original", img), ("Equalized", equalized), ("Blurred", blurred)]

    for i, (title, image) in enumerate(steps):
        if len(image.shape) == 2:  # Grayscale
            axes[i].imshow(image, cmap='gray')
        else:
            axes[i].imshow(cv2.cvtColor(image, cv2.COLOR_BGR2RGB))
        axes[i].set_title(title)
        axes[i].axis('off')

    plt.suptitle("Preprocessing Steps (SmileAlign AI)", fontsize=16)
    plt.tight_layout()
    plt.savefig("preprocessing_steps.png", dpi=300)
    plt.show()

    print("Preprocessing steps saved as preprocessing_steps.png")
    return blurred
