# ====== Imports ======
import os
import numpy as np
import pandas as pd
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import classification_report, confusion_matrix, roc_auc_score
import torch
import torch.nn as nn
from torch.utils.data import Dataset, DataLoader, TensorDataset
import torch.optim as optim
import matplotlib.pyplot as plt
from captum.attr import IntegratedGradients

# ====== Config ======
SEED = 42
torch.manual_seed(SEED)
np.random.seed(SEED)

DATA_CSV = "/path/to/dataset.csv"  # <<--- CHANGE to your CSV path
BATCH_SIZE = 128
LR = 1e-3
EPOCHS = 20
EPS_FGSM = 0.01  # adversarial perturbation magnitude for FGSM evaluation

# ====== Utility: load dataset ======
if not os.path.exists(DATA_CSV):
    raise FileNotFoundError(f"Dataset not found. Update DATA_CSV path. Current: {DATA_CSV}")

df = pd.read_csv(DATA_CSV)
if 'label' not in df.columns:
    raise ValueError("CSV must contain a 'label' column with 0/1 values (benign/malicious).")

# Separate features and label
X = df.drop(columns=['label']).values.astype(np.float32)
y = df['label'].values.astype(np.int64)

# Train/test split
X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2, random_state=SEED, stratify=y)

# Standardize features
scaler = StandardScaler()
X_train = scaler.fit_transform(X_train)
X_test = scaler.transform(X_test)

# Convert to torch tensors & dataloaders
train_dataset = TensorDataset(torch.from_numpy(X_train), torch.from_numpy(y_train))
test_dataset = TensorDataset(torch.from_numpy(X_test), torch.from_numpy(y_test))

train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, shuffle=True)
test_loader = DataLoader(test_dataset, batch_size=BATCH_SIZE, shuffle=False)

input_dim = X_train.shape[1]
print(f"Input features: {input_dim}, Train samples: {len(train_dataset)}, Test samples: {len(test_dataset)}")

# ====== Model definition ======
class SimpleFFN(nn.Module):
    def __init__(self, input_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(input_dim, 256),
            nn.ReLU(),
            nn.BatchNorm1d(256),
            nn.Dropout(0.3),
            nn.Linear(256, 128),
            nn.ReLU(),
            nn.BatchNorm1d(128),
            nn.Dropout(0.2),
            nn.Linear(128, 2)  # 2 classes
        )

    def forward(self, x):
        return self.net(x)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model = SimpleFFN(input_dim).to(device)
criterion = nn.CrossEntropyLoss()
optimizer = optim.Adam(model.parameters(), lr=LR)

# ====== Training function ======
def train_one_epoch(model, loader, optimizer, criterion, adv_train=False, eps=0.01):
    model.train()
    total_loss = 0.0
    for xb, yb in loader:
        xb, yb = xb.to(device), yb.to(device)
        optimizer.zero_grad()

        outputs = model(xb)
        loss = criterion(outputs, yb)

        # optional adversarial training: generate FGSM adversarial examples and include them in the loss
        if adv_train:
            xb.requires_grad = True
            loss.backward(retain_graph=True)
            data_grad = xb.grad.data
            # FGSM perturbation
            perturbed = xb + eps * data_grad.sign()
            perturbed = torch.clamp(perturbed, min=torch.tensor(-10.0).to(device), max=torch.tensor(10.0).to(device))
            # Recompute loss on perturbed
            outputs_adv = model(perturbed.detach())
            loss_adv = criterion(outputs_adv, yb)
            # Combine
            loss = 0.5 * loss + 0.5 * loss_adv
            optimizer.zero_grad()

        loss.backward()
        optimizer.step()
        total_loss += loss.item() * xb.size(0)
    return total_loss / len(loader.dataset)

# ====== FGSM attack (for evaluation) ======
def fgsm_attack(model, x, y, eps):
    x_adv = x.clone().detach().to(device)
    x_adv.requires_grad = True
    outputs = model(x_adv)
    loss = criterion(outputs, y)
    model.zero_grad()
    loss.backward()
    # sign of gradient
    sign_data_grad = x_adv.grad.data.sign()
    perturbed = x_adv + eps * sign_data_grad
    return perturbed.detach()

# ====== Evaluation function ======
def evaluate(model, loader):
    model.eval()
    ys, preds, probs = [], [], []
    with torch.no_grad():
        for xb, yb in loader:
            xb, yb = xb.to(device), yb.to(device)
            out = model(xb)
            p = torch.softmax(out, dim=1)[:,1].cpu().numpy()
            pred = out.argmax(dim=1).cpu().numpy()
            ys.append(yb.cpu().numpy())
            preds.append(pred)
            probs.append(p)
    ys = np.concatenate(ys)
    preds = np.concatenate(preds)
    probs = np.concatenate(probs)
    print(classification_report(ys, preds, digits=4))
    try:
        auc = roc_auc_score(ys, probs)
        print(f"AUC: {auc:.4f}")
    except:
        pass
    return ys, preds, probs

# ====== Training loop (clean training) ======
print("=== Clean training ===")
for epoch in range(1, EPOCHS+1):
    loss = train_one_epoch(model, train_loader, optimizer, criterion, adv_train=False)
    if epoch % 2 == 0 or epoch == 1:
        print(f"Epoch {epoch}/{EPOCHS}, Loss: {loss:.4f}")

print("\nEvaluation on clean test set:")
clean_ys, clean_preds, clean_probs = evaluate(model, test_loader)

# ====== Evaluate robustness under FGSM ======
print("\n=== FGSM evaluation (epsilon = {:.4f}) ===".format(EPS_FGSM))
# Build an adversarial test loader (on-the-fly)
model.eval()
adv_ys, adv_preds, adv_probs = [], [], []
with torch.no_grad():
    for xb, yb in test_loader:
        xb, yb = xb.to(device), yb.to(device)
        xb_adv = fgsm_attack(model, xb, yb, EPS_FGSM)
        out_adv = model(xb_adv)
        p = torch.softmax(out_adv, dim=1)[:,1].cpu().numpy()
        pred = out_adv.argmax(dim=1).cpu().numpy()
        adv_ys.append(yb.cpu().numpy())
        adv_preds.append(pred)
        adv_probs.append(p)

adv_ys = np.concatenate(adv_ys)
adv_preds = np.concatenate(adv_preds)
adv_probs = np.concatenate(adv_probs)
print(classification_report(adv_ys, adv_preds, digits=4))
try:
    print("AUC on adversarial examples:", roc_auc_score(adv_ys, adv_probs))
except:
    pass

# ====== Optional: Adversarial training (retrain model) ======
print("\n=== Adversarial training (FGSM) ===")
# Re-init model for adversarial training (fresh model)
adv_model = SimpleFFN(input_dim).to(device)
optimizer_adv = optim.Adam(adv_model.parameters(), lr=LR)

EPOCHS_ADV = 12
for epoch in range(1, EPOCHS_ADV+1):
    loss = train_one_epoch(adv_model, train_loader, optimizer_adv, criterion, adv_train=True, eps=EPS_FGSM)
    if epoch % 2 == 0 or epoch == 1:
        print(f"[ADV] Epoch {epoch}/{EPOCHS_ADV}, Loss: {loss:.4f}")

print("\nEvaluation of adversarially trained model on clean test set:")
evaluate(adv_model, test_loader)

print("\nEvaluation of adversarially trained model on FGSM adv examples:")
adv_ys2, adv_preds2, adv_probs2 = [], [], []
with torch.no_grad():
    for xb, yb in test_loader:
        xb, yb = xb.to(device), yb.to(device)
        xb_adv = fgsm_attack(adv_model, xb, yb, EPS_FGSM)
        out_adv = adv_model(xb_adv)
        p = torch.softmax(out_adv, dim=1)[:,1].cpu().numpy()
        pred = out_adv.argmax(dim=1).cpu().numpy()
        adv_ys2.append(yb.cpu().numpy())
        adv_preds2.append(pred)
        adv_probs2.append(p)

adv_ys2 = np.concatenate(adv_ys2)
adv_preds2 = np.concatenate(adv_preds2)
print(classification_report(adv_ys2, adv_preds2, digits=4))
try:
    print("AUC:", roc_auc_score(adv_ys2, np.concatenate(adv_probs2)))
except:
    pass

# ====== Explainability using Captum (Integrated Gradients) ======
print("\n=== Explainability (Integrated Gradients) example ===")
ig = IntegratedGradients(adv_model)

