# ============================================================
# 8. RUN SELECTED MODEL
# ============================================================

def run_model(option, image_path):

    config = MODELS[option]

    print()
    print("==============================================")
    print("             AI ANALYSIS STARTED")
    print("==============================================")

    print("Selected analysis:", option)

    print()
    print("Please wait...")
    print()

    try:

        # ====================================================
        # NORMAL ROBOFLOW MODEL
        # ====================================================

        if config["type"] == "model":

            result = CLIENT.infer(
                image_path,
                model_id=config["model_id"]
            )


        # ====================================================
        # ROBOFLOW WORKFLOW
        # ====================================================

        elif config["type"] == "workflow":

            result = CLIENT.run_workflow(

                workspace_name=config[
                    "workspace_name"
                ],

                workflow_id=config[
                    "workflow_id"
                ],

                images={
                    "image": image_path
                },

                parameters={
                    "classes": config[
                        "classes"
                    ]
                },

                use_cache=True
            )


        else:

            raise ValueError(
                "Invalid model configuration."
            )


        print("✓ AI analysis completed.")

        return result


    except Exception as e:

        print()
        print("❌ MODEL ERROR")
        print("----------------------------------------------")
        print(str(e))
        print("----------------------------------------------")

        return None


# ============================================================
# 9. FIND PREDICTIONS
# ============================================================

def extract_predictions(result):

    if result is None:

        return []


    # Standard Roboflow model response

    if isinstance(result, dict):

        if "predictions" in result:

            return result["predictions"]


    # Workflow responses can have nested structures

    if isinstance(result, list):

        for item in result:

            if isinstance(item, dict):

                if "predictions" in item:

                    return item["predictions"]


    return []


# ============================================================
# 10. PRINT DETECTION SUMMARY
# ============================================================

def show_detection_summary(
    option,
    result
):

    predictions = extract_predictions(
        result
    )

    print()
    print("==============================================")
    print("              ANALYSIS SUMMARY")
    print("==============================================")

    print()
    print("Analysis:", option)

    print(
        "Number of detections:",
        len(predictions)
    )

    print()

    if not predictions:

        print(
            "No standard predictions were found."
        )

        print(
            "The raw Roboflow result is shown below."
        )

        return


    # --------------------------------------------------------
    # COUNT CLASSES
    # --------------------------------------------------------

    class_counts = {}

    for prediction in predictions:

        class_name = prediction.get(
            "class",
            "Unknown"
        )

        class_counts[class_name] = (
            class_counts.get(
                class_name,
                0
            ) + 1
        )


    print("Detected categories:")
    print()

    for class_name, count in class_counts.items():

        print(
            f"  • {class_name}: {count}"
        )


    print()

    # --------------------------------------------------------
    # CONFIDENCE
    # --------------------------------------------------------

    confidences = []

    for prediction in predictions:

        confidence = prediction.get(
            "confidence"
        )

        if confidence is not None:

            confidences.append(
                float(confidence)
            )


    if confidences:

        average_confidence = (
            sum(confidences)
            / len(confidences)
        )

        print(
            "Average confidence:",
            f"{average_confidence * 100:.2f}%"
        )


# ============================================================
# 11. CREATE ANNOTATED IMAGE
# ============================================================

def create_annotated_image(
    image_path,
    result,
    option
):

    img = cv2.imread(image_path)

    if img is None:

        raise ValueError(
            "Could not load image."
        )


    predictions = extract_predictions(
        result
    )


    # --------------------------------------------------------
    # COLORS
    # --------------------------------------------------------

    colors = [
        (0, 255, 0),
        (255, 0, 0),
        (0, 255, 255),
        (255, 0, 255),
        (0, 165, 255),
        (255, 255, 0)
    ]


    # --------------------------------------------------------
    # DRAW PREDICTIONS
    # --------------------------------------------------------

    for index, prediction in enumerate(
        predictions
    ):

        color = colors[
            index % len(colors)
        ]


        class_name = prediction.get(
            "class",
            "Unknown"
        )


        confidence = prediction.get(
            "confidence",
            0
        )


        # ====================================================
        # BOUNDING BOX
        # ====================================================

        if all(
            key in prediction
            for key in [
                "x",
                "y",
                "width",
                "height"
            ]
        ):

            x = float(
                prediction["x"]
            )

            y = float(
                prediction["y"]
            )

            width = float(
                prediction["width"]
            )

            height = float(
                prediction["height"]
            )


            x1 = int(
                x - width / 2
            )

            y1 = int(
                y - height / 2
            )

            x2 = int(
                x + width / 2
            )

            y2 = int(
                y + height / 2
            )


            cv2.rectangle(
                img,
                (x1, y1),
                (x2, y2),
                color,
                3
            )


            label = (
                f"{class_name} "
                f"{confidence * 100:.1f}%"
            )


            cv2.rectangle(
                img,
                (
                    x1,
                    max(0, y1 - 35)
                ),
                (
                    x1 + 250,
                    y1
                ),
                color,
                -1
            )


            cv2.putText(
                img,
                label,
                (
                    x1 + 5,
                    max(25, y1 - 10)
                ),
                cv2.FONT_HERSHEY_SIMPLEX,
                0.65,
                (0, 0, 0),
                2,
                cv2.LINE_AA
            )


        # ====================================================
        # SEGMENTATION POLYGON
        # ====================================================

        elif (
            "points" in prediction
            and prediction["points"]
        ):

            points = np.array(
                [
                    [
                        int(point["x"]),
                        int(point["y"])
                    ]

                    for point
                    in prediction["points"]
                ],
                dtype=np.int32
            )


            cv2.polylines(
                img,
                [points],
                True,
                color,
                3
            )


            cv2.fillPoly(
                img,
                [points],
                color
            )


            # Make overlay transparent

            overlay = img.copy()

            cv2.fillPoly(
                overlay,
                [points],
                color
            )

            img = cv2.addWeighted(
                overlay,
                0.25,
                img,
                0.75,
                0
            )


            center_x = int(
                np.mean(points[:, 0])
            )

            center_y = int(
                np.mean(points[:, 1])
            )


            label = (
                f"{class_name} "
                f"{confidence * 100:.1f}%"
            )


            cv2.putText(
                img,
                label,
                (
                    center_x,
                    center_y
                ),
                cv2.FONT_HERSHEY_SIMPLEX,
                0.7,
                color,
                2,
                cv2.LINE_AA
            )


    # ========================================================
    # SAVE IMAGE
    # ========================================================

    safe_name = (
        option
        .lower()
        .replace(" ", "_")
        .replace("/", "_")
    )


    output_path = (
        f"{safe_name}_annotated.jpg"
    )


    cv2.imwrite(
        output_path,
        img
    )


    return output_path


# ============================================================
