# ============================================================
# 13. SAVE JSON RESULT
# ============================================================

def save_json_result(
    option,
    result
):

    safe_name = (
        option
        .lower()
        .replace(" ", "_")
        .replace("/", "_")
    )


    json_path = (
        f"{safe_name}_result.json"
    )


    with open(
        json_path,
        "w"
    ) as file:

        json.dump(
            result,
            file,
            indent=4,
            default=str
        )


    print(
        "✓ JSON result saved:",
        json_path
    )


    return json_path


