# ============================================================
# --- Helper functions ---
# ============================================================

def image_to_base64(image_path):
    with open(image_path, "rb") as img_file:
        return base64.b64encode(img_file.read()).decode("utf-8")


def compute_concavity(polygon):
    convex_hull = polygon.convex_hull
    if not convex_hull.is_valid or convex_hull.area <= 0:
        return 0.0
    area = polygon.area
    ch_area = convex_hull.area
    return max(0.0, (ch_area - area) / ch_area)


def normalize_prediction_to_poly(p):
    """Turn one raw prediction dict (Roboflow-style) into a shapely Polygon + bbox info."""
    w = p.get("width", 0)
    h = p.get("height", 0)
    if w < MIN_BOX_WH or h < MIN_BOX_WH:
        return None

    if "points" in p and p["points"]:
        pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
    else:
        x, y = p["x"], p["y"]
        x_min, x_max = x - w / 2, x + w / 2
        y_min, y_max = y - h / 2, y + h / 2
        pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)

    poly = Polygon(pts)
    if not poly.is_valid or poly.area <= 0:
        return None

    bx_min, by_min, bx_max, by_max = poly.bounds
    cx, cy = (bx_min + bx_max) / 2, (by_min + by_max) / 2

    return {
        "class": p.get("class", "object"),
        "conf": p.get("confidence", 1.0),
        "pts": pts.astype(int),
        "poly": poly,
        "cx": cx, "cy": cy,
        "bx_min": bx_min, "bx_max": bx_max,
        "by_min": by_min, "by_max": by_max,
        "w_px": bx_max - bx_min, "h_px": by_max - by_min,
        "area_px": poly.area,
    }


def find_predictions_list(obj):
    """Recursively search a nested dict/list (e.g. workflow output) for a
    list of prediction-like dicts (containing x/y/width/height or points)."""
    if isinstance(obj, list):
        if obj and isinstance(obj[0], dict) and (
            ("x" in obj[0] and "y" in obj[0]) or "points" in obj[0]
        ):
            return obj
        for item in obj:
            found = find_predictions_list(item)
            if found:
                return found
    elif isinstance(obj, dict):
        if "predictions" in obj and isinstance(obj["predictions"], list):
            return obj["predictions"]
        for v in obj.values():
            found = find_predictions_list(v)
            if found:
                return found
    return None


# ============================================================
# --- Inference runners for each model "kind" ---
# ============================================================

def run_legacy_project(cfg, image_path):
    rf = Roboflow(api_key=cfg["api_key"])
    project = rf.workspace(cfg["workspace"]).project(cfg["project"])
    model = project.version(cfg["version"]).model
    pred_json = model.predict(image_path, confidence=CONFIDENCE).json()
    return pred_json.get("predictions", [])


def run_infer_model(cfg, image_path):
    client = InferenceHTTPClient(
        api_url="https://serverless.roboflow.com",
        api_key=cfg["api_key"],
    ).configure(InferenceConfiguration(api_key_transport="header"))
    result = client.infer(image_path, model_id=cfg["model_id"])
    result_json = result if isinstance(result, dict) else result.json()
    return result_json.get("predictions", []) or find_predictions_list(result_json) or []


def run_workflow(cfg, image_path):
    client = InferenceHTTPClient(
        api_url="https://serverless.roboflow.com",
        api_key=cfg["api_key"],
    ).configure(InferenceConfiguration(api_key_transport="header"))
    result = client.run_workflow(
        workspace_name=cfg["workspace_name"],
        workflow_id=cfg["workflow_id"],
        images={"image": image_path},
        parameters=cfg.get("parameters", {}),
        use_cache=True,
    )
    return find_predictions_list(result) or []


def get_raw_predictions(model_key, image_path):
    cfg = MODELS[model_key]
    kind = cfg["kind"]
    if kind == "legacy_project":
        return run_legacy_project(cfg, image_path)
    elif kind == "infer_model":
        return run_infer_model(cfg, image_path)
    elif kind == "workflow":
        return run_workflow(cfg, image_path)
    else:
        raise ValueError(f"Unknown model kind: {kind}")


# ============================================================
# --- Tooth-specific deep analysis (model 1 only) ---
# ============================================================

def analyze_tooth_model(detections, img):
    y_coords = np.array([[d["cy"]] for d in detections])
    n_clusters = 2 if len(detections) >= 6 else 1
    if len(detections) >= 2:
        km = KMeans(n_clusters=n_clusters, n_init=5, random_state=0)
        labels = km.fit_predict(y_coords)
    else:
        labels = np.zeros(len(detections))

    arch_map = {}
    for d, lab in zip(detections, labels):
        arch_map.setdefault(lab, []).append(d)
    label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
    arches = {arch_id + 1: arch_map[old_id] for arch_id, old_id in enumerate(label_order)}

    annot = img.copy()
    teeth_rows, gap_rows, cavein_rows = [], [], []
    px_per_mm = None

    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        if len(d_sorted) > USE_REF_TOOTH_IDX:
            ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
            if ref_w_px > 0:
                px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH
            break

    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        col = COLOR_ARCH[(arch_id - 1) % len(COLOR_ARCH)]

        for idx, d in enumerate(d_sorted):
            cv2.polylines(annot, [d["pts"]], True, col, 2)
            label = f"A{arch_id}T{idx + 1}"
            cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.4, col, 1, cv2.LINE_AA)

            ch = d["poly"].convex_hull
            area_ratio = d["area_px"] / ch.area if ch.area > 0 else 1.0
            concavity = compute_concavity(d["poly"])
            is_cavein = (area_ratio < CAVEIN_AREA_RATIO) or (concavity > CAVEIN_CONCAVITY_THRESH)
            treatment, timeline = "N/A", "N/A"
            if is_cavein:
                cv2.putText(annot, "Cave-in", (int(d["cx"]), int(d["cy"])),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 0, 255), 1, cv2.LINE_AA)
                treatment = "Restoration (filling or buildup)" if area_ratio > 0.3 else "Endodontic + Crown or Extraction"
                timeline = "1-2 visits (2-4 weeks)" if area_ratio > 0.3 else "3-6 visits (4-12 weeks)"
                cavein_rows.append({
                    "arch": arch_id, "tooth": idx + 1,
                    "area_ratio": f"{area_ratio:.2f}", "concavity": f"{concavity:.2f}",
                    "treatment": treatment, "timeline": timeline,
                })

            teeth_rows.append({
                "arch": arch_id, "tooth": idx + 1, "class": d["class"],
                "confidence": f"{d['conf']:.2f}",
                "width_px": f"{d['w_px']:.1f}",
                "width_mm": f"{d['w_px'] / px_per_mm:.1f}" if px_per_mm else "N/A",
                "height_px": f"{d['h_px']:.1f}", "area_px": f"{d['area_px']:.1f}",
                "is_cavein": "Yes" if is_cavein else "No",
                "cavein_treatment": treatment, "cavein_timeline": timeline,
            })

        for i in range(len(d_sorted) - 1):
            gap_px = max(0, d_sorted[i + 1]["bx_min"] - d_sorted[i]["bx_max"])
            gap_mm = gap_px / px_per_mm if px_per_mm else None
            if gap_px > GAP_ALERT_PX:
                mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i + 1]["bx_min"]) / 2)
                mid_y = int((d_sorted[i]["cy"] + d_sorted[i + 1]["cy"]) / 2)
                cv2.putText(annot, f"{gap_px:.0f}px", (mid_x, mid_y),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, COLOR_GAP, 1, cv2.LINE_AA)
                if gap_px < 25:
                    cap_type, timeline = "Composite Resin Crown, Zirconia Crown, or PFM Crown", "2-3 weeks"
                elif gap_px < 50:
                    cap_type, timeline = "Zirconia or Porcelain-Fused-to-Metal Bridge", "3-6 weeks"
                else:
                    cap_type, timeline = "Multi-unit Bridge or Orthodontic Alignment + Prosthetics", "6-12+ weeks"
                gap_rows.append({
                    "arch": arch_id, "left_tooth": i + 1, "right_tooth": i + 2,
                    "gap_px": f"{gap_px:.1f}", "gap_mm": f"{gap_mm:.1f}" if gap_mm else "N/A",
                    "cap_type": cap_type, "timeline": timeline,
                })

    all_cx = np.array([d["cx"] for d in detections])
    align_std = np.std(all_cx)
    alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted (Misaligned)"
    misaligned_teeth = [f"A{row['arch']}T{row['tooth']}" for row in teeth_rows] if align_std >= ALIGN_ALERT_PX else []

    return annot, teeth_rows, gap_rows, cavein_rows, alignment, misaligned_teeth


# ============================================================
# --- Treatment-suggestion rules (models 2, 3, 4) ---
# ============================================================
# Severity is inferred from shape irregularity (area_ratio / concavity),
# same signals already used for cave-in detection in the tooth model.
# Class-name matching is a simple substring/keyword match against whatever
# label your model returns, so it degrades gracefully to DEFAULT_TREATMENT
# if a class name isn't in the table below.

def determine_severity(area_ratio, concavity):
    if area_ratio < 0.30 or concavity > 0.35:
        return "severe"
    elif area_ratio < CAVEIN_AREA_RATIO or concavity > CAVEIN_CONCAVITY_THRESH:
        return "moderate"
    else:
        return "mild"


DEFAULT_TREATMENT = {
    "severe":   ("Clinical evaluation and further diagnostic workup recommended", "1-2 weeks"),
    "moderate": ("Follow-up evaluation with a professional suggested", "2-4 weeks"),
    "mild":     ("Monitor; routine follow-up", "Routine checkup"),
}

TREATMENT_RULES = {
    # --- Model 2: Oral Cancer Screening ---
    "2": [
        (["cancer", "tumor", "malignan", "carcinoma"], {
            "severe":   ("Urgent biopsy and referral to an oral & maxillofacial oncologist", "Immediate (1-2 weeks)"),
            "moderate": ("Biopsy recommended to rule out malignancy", "2-3 weeks"),
            "mild":     ("Clinical monitoring; re-screen shortly", "2-4 weeks follow-up"),
        }),
        (["leukoplakia", "erythroplakia", "dysplasia"], {
            "severe":   ("Biopsy plus specialist referral; smoking/alcohol cessation counseling", "2-4 weeks"),
            "moderate": ("Biopsy recommended; lifestyle/risk-factor counseling", "4-6 weeks"),
            "mild":     ("Monitor lesion; reduce risk factors (tobacco/alcohol)", "6-8 week review"),
        }),
        (["ulcer", "lesion", "sore", "patch"], {
            "severe":   ("Biopsy if non-healing beyond 2 weeks", "2 weeks"),
            "moderate": ("Topical treatment; monitor healing closely", "1-2 weeks"),
            "mild":     ("Self-care and monitoring", "1 week recheck"),
        }),
        (["normal", "healthy"], {
            "severe": ("N/A", "N/A"), "moderate": ("N/A", "N/A"),
            "mild":   ("No treatment needed; routine screening", "Routine (6-12 months)"),
        }),
    ],
    # --- Model 3: Teeth Cavity / Caries / Crack Workflow ---
    "3": [
        (["cavity"], {
            "severe":   ("Root canal treatment + crown, or extraction if unsalvageable", "3-5 visits (4-8 weeks)"),
            "moderate": ("Restorative filling (composite/amalgam)", "1-2 visits (1-3 weeks)"),
            "mild":     ("Fluoride treatment / sealant; monitor", "1 visit (1-2 weeks)"),
        }),
        (["caries"], {
            "severe":   ("Root canal treatment + crown", "3-5 visits (4-8 weeks)"),
            "moderate": ("Restorative filling", "1-2 visits (2-4 weeks)"),
            "mild":     ("Remineralization therapy; monitor", "Follow-up in 4-6 weeks"),
        }),
        (["crack"], {
            "severe":   ("Crown, root canal, or extraction depending on crack depth", "2-4 visits (3-6 weeks)"),
            "moderate": ("Dental bonding or crown", "1-2 visits (2-3 weeks)"),
            "mild":     ("Monitor; avoid hard foods/biting pressure", "Routine follow-up"),
        }),
        (["tooth"], {
            "severe": ("N/A", "N/A"), "moderate": ("N/A", "N/A"),
            "mild":   ("No treatment needed; maintain oral hygiene", "Routine 6-month checkup"),
        }),
    ],
    # --- Model 4: Tongue Health ---
    "4": [
        (["coating", "plaque", "fur"], {
            "severe":   ("Address underlying cause (infection/GI); improve oral hygiene", "1-2 weeks"),
            "moderate": ("Tongue scraping; improved oral hygiene routine", "1-2 weeks self-care"),
            "mild":     ("Routine hygiene", "Routine"),
        }),
        (["discoloration", "lesion", "patch"], {
            "severe":   ("Clinical evaluation to rule out infection or systemic condition", "1-2 weeks"),
            "moderate": ("Monitor; evaluate if it persists", "2-3 weeks"),
            "mild":     ("Monitor", "Routine follow-up"),
        }),
        (["fissured", "geographic", "crack"], {
            "severe":   ("Evaluate for irritation/pain management", "2-3 weeks"),
            "moderate": ("Usually benign; monitor", "Routine"),
            "mild":     ("No treatment typically needed", "Routine"),
        }),
        (["normal", "healthy"], {
            "severe": ("N/A", "N/A"), "moderate": ("N/A", "N/A"),
            "mild":   ("No treatment needed", "Routine checkup"),
        }),
    ],
}


def suggest_treatment(model_key, det_class, area_ratio, concavity):
    """Return (treatment, timeline) for a detection, using class-keyword
    matching + severity inferred from shape irregularity."""
    severity = determine_severity(area_ratio, concavity)
    cls_lower = (det_class or "").lower()
    for keywords, sev_map in TREATMENT_RULES.get(model_key, []):
        if any(k in cls_lower for k in keywords):
            return sev_map.get(severity, DEFAULT_TREATMENT[severity])
    return DEFAULT_TREATMENT[severity]


# ============================================================
# --- Generic analysis (models 2, 3, 4) ---
# ============================================================

def analyze_generic_model(model_key, detections, img):
    annot = img.copy()
    rows, notable_rows = [], []

    for idx, d in enumerate(sorted(detections, key=lambda d: (d["cy"], d["cx"]))):
        cv2.polylines(annot, [d["pts"]], True, COLOR_GENERIC, 2)
        label = f"{d['class']} #{idx + 1} ({d['conf']:.2f})"
        cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.45, COLOR_GENERIC, 1, cv2.LINE_AA)

        ch = d["poly"].convex_hull
        area_ratio = d["area_px"] / ch.area if ch.area > 0 else 1.0
        concavity = compute_concavity(d["poly"])
        is_notable = (area_ratio < CAVEIN_AREA_RATIO) or (concavity > CAVEIN_CONCAVITY_THRESH)

        treatment, timeline = suggest_treatment(model_key, d["class"], area_ratio, concavity)

        if is_notable:
            cv2.putText(annot, "Irregular", (int(d["cx"]), int(d["cy"])),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 0, 255), 1, cv2.LINE_AA)
            notable_rows.append({
                "index": idx + 1, "class": d["class"],
                "area_ratio": f"{area_ratio:.2f}", "concavity": f"{concavity:.2f}",
                "treatment": treatment, "timeline": timeline,
            })

        rows.append({
            "index": idx + 1, "class": d["class"], "confidence": f"{d['conf']:.2f}",
            "width_px": f"{d['w_px']:.1f}", "height_px": f"{d['h_px']:.1f}",
            "area_px": f"{d['area_px']:.1f}", "is_notable": "Yes" if is_notable else "No",
            "treatment": treatment, "timeline": timeline,
        })

    return annot, rows, notable_rows


