def main(model_key, image_path):
    cfg = MODELS[model_key]
    raw_preds = get_raw_predictions(model_key, image_path)

    img = cv2.imread(image_path)
    if img is None:
        raise RuntimeError(f"Could not read image: {image_path}")

    env = Environment(autoescape=select_autoescape(['html', 'xml']))

    # --- Classification-style response (e.g. Tongue Health): no boxes,
    # just a set of predicted classes with confidences. ---
    if is_classification_payload(raw_preds):
        class_rows = normalize_classification_predictions(raw_preds)
        if not class_rows:
            raise ValueError("No usable classification result returned. Try a clearer image.")

        annot, rows = analyze_classification_model(model_key, class_rows, img)
        template = env.from_string(CLASSIFICATION_TEMPLATE)
        with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as tf:
            tmp_path = tf.name
            cv2.imwrite(tmp_path, cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
        img_data = image_to_base64(tmp_path)
        os.unlink(tmp_path)

        html_report = template.render(
            title=f"{cfg['name']} Report", model_name=cfg["name"], patient_id=PATIENT_ID,
            image_base64=img_data, classes_table=rows,
        )

    else:
        # --- Detection/segmentation-style response: boxes/polygons. ---
        detections = []
        for p in raw_preds:
            norm = normalize_prediction_to_poly(p)
            if norm:
                detections.append(norm)

        if not detections:
            raise ValueError("No usable detections. Try lowering confidence or uploading a clearer image.")

        if model_key == "1":
            annot, teeth_rows, gap_rows, cavein_rows, alignment, misaligned_teeth = analyze_tooth_model(detections, img)
            template = env.from_string(TOOTH_TEMPLATE)
            with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as tf:
                tmp_path = tf.name
                cv2.imwrite(tmp_path, cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
            img_data = image_to_base64(tmp_path)
            os.unlink(tmp_path)

            html_report = template.render(
                title=REPORT_TITLE, model_name=cfg["name"], patient_id=PATIENT_ID,
                image_base64=img_data, teeth_table=teeth_rows, gaps_table=gap_rows,
                caveins_table=cavein_rows, alignment=alignment,
                misaligned_teeth=", ".join(misaligned_teeth) if misaligned_teeth else "None",
            )
        else:
            annot, rows, notable_rows = analyze_generic_model(model_key, detections, img)
            template = env.from_string(GENERIC_TEMPLATE)
            with tempfile.NamedTemporaryFile(suffix=".jpg", delete=False) as tf:
                tmp_path = tf.name
                cv2.imwrite(tmp_path, cv2.cvtColor(annot, cv2.COLOR_BGR2RGB))
            img_data = image_to_base64(tmp_path)
            os.unlink(tmp_path)

            html_report = template.render(
                title=f"{cfg['name']} Report", model_name=cfg["name"], patient_id=PATIENT_ID,
                image_base64=img_data, detections_table=rows, notable_table=notable_rows,
            )

    html_path = f"report_model{model_key}.html"
    with open(html_path, "w") as f:
        f.write(html_report)
    print(f"\nHTML report saved to {html_path}")

    pdf_options = {"encoding": "UTF-8", "no-outline": None, "quiet": ""}
    pdf_path = f"report_model{model_key}.pdf"
    pdfkit.from_string(html_report, pdf_path, options=pdf_options)
    print(f"PDF report saved to {pdf_path}")

    return html_path, pdf_path


def choose_model():
    print("\nSelect which model to run:")
    for key, cfg in MODELS.items():
        print(f"  {key}) {cfg['name']}")
    choice = input("Enter option number (1-4): ").strip()
    if choice not in MODELS:
        raise ValueError("Invalid selection. Please choose 1, 2, 3, or 4.")
    return choice


if __name__ == "__main__":
    model_key = choose_model()

    print("\nUpload your image...")
    uploaded = files.upload()
    if not uploaded:
        raise ValueError("No file uploaded. Please upload an image.")
    image_path = list(uploaded.keys())[0]

    html_path, pdf_path = main(model_key, image_path)

    files.download(pdf_path)

"""
Dental AI Multi-Model Analysis Tool
====================================
Upload an image, pick which model to run, and get an annotated image
+ HTML/PDF report back.

Models included:
  1) Cavity Detection (tooth-level project model, legacy `roboflow` SDK)
  2) Oral Cancer Screening (intra-oral-scanner)
  3) Teeth Alignment, Caries, Cavity & Crack Detection (Roboflow Workflow)
  4) Tongue Health Analysis

Run this in Google Colab (it uses google.colab.files for upload/download).
Requires: opencv-python, numpy, shapely, scikit-learn, jinja2, pdfkit, requests,
          wkhtmltopdf (system package for pdfkit).

    !pip install -q opencv-python-headless numpy shapely scikit-learn jinja2 pdfkit requests
    !apt-get -y install wkhtmltopdf

Note: this talks to Roboflow directly over plain HTTP (via `requests`) instead
of the `roboflow` / `inference-sdk` packages, since those packages pin exact
opencv/numpy versions that frequently fail to install on newer Colab Python
runtimes. Roboflow's hosted inference and workflow endpoints are just REST
APIs, so no SDK is actually required.
"""

import os
import cv2
import numpy as np
import requests
from shapely.geometry import Polygon
from sklearn.cluster import KMeans
from jinja2 import Environment, select_autoescape
import pdfkit
import tempfile
import base64

from google.colab import files

# ============================================================
# --- Configuration: put each model's API key/details here ---
# ============================================================

MODELS = {
    "1": {
        "name": "Cavity Detection (tooth-level project model)",
        "kind": "hosted",                  # plain REST hosted-inference call
        "api_key": "DFlrjZHolOe8aC38zXZS",
        "model_path": "cavity-detection-pe9t4/1",   # {project}/{version}
    },
    "2": {
        "name": "Oral Cancer Screening",
        "kind": "hosted",
        "api_key": "8r0ktXGodLGr47qKcxNt",
        "model_path": "intra-oral-scanner-r4xwu/2",
    },
    "3": {
        "name": "Teeth Alignment, Caries, Cavity & Crack Detection (Workflow)",
        "kind": "workflow",                 # calls the Workflows REST endpoint
        "api_key": "8r0ktXGodLGr47qKcxNt",
        "workspace_name": "sp-n8934",
        "workflow_id": "general-segmentation-api-7",
        "parameters": {"classes": "Crack, Tooth, Caries, Cavity"},
    },
    "4": {
        "name": "Tongue Health Analysis",
        "kind": "hosted",
        "api_key": "8r0ktXGodLGr47qKcxNt",
        "model_path": "tongue-tod5c/1",
    },
}

CONFIDENCE = 40                               # confidence threshold (%)
MIN_BOX_WH = 10                               # minimum detection size (px)
GAP_ALERT_PX = 15                             # gap alert threshold (px) - tooth model only
ALIGN_MODERATE_PX = 25                        # alignment std-dev "moderate misalignment" threshold
ALIGN_SEVERE_PX = 45                          # alignment std-dev "severe misalignment" threshold
ALIGN_ALERT_PX = ALIGN_MODERATE_PX            # kept for backward compatibility with model-1 code

KNOWN_MM_PER_TOOTH = 8.5                      # average incisor width (mm) - tooth model only
USE_REF_TOOTH_IDX = 0

COLOR_LABEL = (0, 255, 0)
COLOR_GAP = (255, 0, 0)
COLOR_ARCH = [(255, 0, 255), (0, 255, 255)]
COLOR_GENERIC = (0, 200, 255)
COLOR_ALIGN = (0, 140, 255)

REPORT_TITLE = "Dental AI Analysis Report"
PATIENT_ID = "P-12345"

CAVEIN_AREA_RATIO = 0.5
CAVEIN_CONCAVITY_THRESH = 0.2

# ============================================================
# --- Helper functions ---
# ============================================================

def image_to_base64(image_path):
    with open(image_path, "rb") as img_file:
        return base64.b64encode(img_file.read()).decode("utf-8")


def compute_concavity(polygon):
    convex_hull = polygon.convex_hull
    if not convex_hull.is_valid or convex_hull.area <= 0:
        return 0.0
    area = polygon.area
    ch_area = convex_hull.area
    return max(0.0, (ch_area - area) / ch_area)


def normalize_prediction_to_poly(p):
    """Turn one raw prediction dict (Roboflow-style) into a shapely Polygon + bbox info."""
    w = p.get("width", 0)
    h = p.get("height", 0)
    if w < MIN_BOX_WH or h < MIN_BOX_WH:
        return None

    if "points" in p and p["points"]:
        pts = np.array([[pt["x"], pt["y"]] for pt in p["points"]], dtype=np.float32)
    else:
        x, y = p["x"], p["y"]
        x_min, x_max = x - w / 2, x + w / 2
        y_min, y_max = y - h / 2, y + h / 2
        pts = np.array([[x_min, y_min], [x_max, y_min], [x_max, y_max], [x_min, y_max]], dtype=np.float32)

    poly = Polygon(pts)
    if not poly.is_valid or poly.area <= 0:
        return None

    bx_min, by_min, bx_max, by_max = poly.bounds
    cx, cy = (bx_min + bx_max) / 2, (by_min + by_max) / 2

    return {
        "class": p.get("class", "object"),
        "conf": p.get("confidence", 1.0),
        "pts": pts.astype(int),
        "poly": poly,
        "cx": cx, "cy": cy,
        "bx_min": bx_min, "bx_max": bx_max,
        "by_min": by_min, "by_max": by_max,
        "w_px": bx_max - bx_min, "h_px": by_max - by_min,
        "area_px": poly.area,
    }


def find_predictions_list(obj):
    """Recursively search a nested dict/list (e.g. workflow output) for a
    list of prediction-like dicts (containing x/y/width/height or points)."""
    if isinstance(obj, list):
        if obj and isinstance(obj[0], dict) and (
            ("x" in obj[0] and "y" in obj[0]) or "points" in obj[0]
        ):
            return obj
        for item in obj:
            found = find_predictions_list(item)
            if found:
                return found
    elif isinstance(obj, dict):
        if "predictions" in obj and isinstance(obj["predictions"], list):
            return obj["predictions"]
        for v in obj.values():
            found = find_predictions_list(v)
            if found:
                return found
    return None


def is_classification_payload(raw_preds):
    """True if raw_preds looks like a classification result (dict of
    class->confidence, or a plain list of class-name strings / class dicts
    with no bounding box) rather than a detection/segmentation result."""
    if isinstance(raw_preds, dict):
        return True
    if isinstance(raw_preds, list) and raw_preds:
        first = raw_preds[0]
        if isinstance(first, str):
            return True
        if isinstance(first, dict) and "x" not in first and "width" not in first and "points" not in first:
            return True
    return False


def normalize_classification_predictions(raw_preds):
    """Turn any of Roboflow's classification response shapes into a flat
    list of {'class':..., 'confidence':...}, sorted by confidence desc."""
    results = []
    if isinstance(raw_preds, dict):
        for cls_name, info in raw_preds.items():
            conf = info.get("confidence", 1.0) if isinstance(info, dict) else 1.0
            results.append({"class": cls_name, "confidence": float(conf)})
    elif isinstance(raw_preds, list):
        for item in raw_preds:
            if isinstance(item, str):
                results.append({"class": item, "confidence": 1.0})
            elif isinstance(item, dict):
                results.append({
                    "class": item.get("class", item.get("top", "unknown")),
                    "confidence": float(item.get("confidence", 1.0)),
                })
    results.sort(key=lambda r: r["confidence"], reverse=True)
    return results


# ============================================================
# --- Inference runners for each model "kind" (plain REST calls) ---
# ============================================================
# No `roboflow` / `inference-sdk` packages needed - both are just thin
# wrappers around these HTTP endpoints, and their pinned dependencies
# (specific opencv/numpy versions) are what break installs on newer Colab
# runtimes. Calling the REST API directly with `requests` avoids that.

def _b64_image(image_path):
    with open(image_path, "rb") as f:
        return base64.b64encode(f.read()).decode("utf-8")


def run_hosted(cfg, image_path):
    """Calls Roboflow's hosted inference API for a single model.
    Works for both classic object-detection/segmentation project models
    and universe models referenced as 'name/version'."""
    url = f"https://detect.roboflow.com/{cfg['model_path']}"
    img_b64 = _b64_image(image_path)
    resp = requests.post(
        url,
        params={"api_key": cfg["api_key"], "confidence": CONFIDENCE},
        data=img_b64,
        headers={"Content-Type": "application/x-www-form-urlencoded"},
        timeout=60,
    )
    if not resp.ok:
        raise RuntimeError(
            f"Roboflow hosted inference failed ({resp.status_code}): {resp.text[:500]}"
        )
    return resp.json().get("predictions", [])


def run_workflow(cfg, image_path):
    """Calls a Roboflow Workflow via its REST endpoint."""
    url = f"https://serverless.roboflow.com/infer/workflows/{cfg['workspace_name']}/{cfg['workflow_id']}"
    img_b64 = _b64_image(image_path)
    inputs = {"image": {"type": "base64", "value": img_b64}}
    inputs.update(cfg.get("parameters", {}))
    body = {"api_key": cfg["api_key"], "inputs": inputs}
    resp = requests.post(url, json=body, timeout=90)
    if not resp.ok:
        raise RuntimeError(
            f"Roboflow workflow call failed ({resp.status_code}): {resp.text[:500]}"
        )
    return find_predictions_list(resp.json()) or []


def get_raw_predictions(model_key, image_path):
    cfg = MODELS[model_key]
    kind = cfg["kind"]
    if kind == "hosted":
        return run_hosted(cfg, image_path)
    elif kind == "workflow":
        return run_workflow(cfg, image_path)
    else:
        raise ValueError(f"Unknown model kind: {kind}")


# ============================================================
# --- Tooth-specific deep analysis (model 1 only) ---
# ============================================================

def analyze_tooth_model(detections, img):
    y_coords = np.array([[d["cy"]] for d in detections])
    n_clusters = 2 if len(detections) >= 6 else 1
    if len(detections) >= 2:
        km = KMeans(n_clusters=n_clusters, n_init=5, random_state=0)
        labels = km.fit_predict(y_coords)
    else:
        labels = np.zeros(len(detections))

    arch_map = {}
    for d, lab in zip(detections, labels):
        arch_map.setdefault(lab, []).append(d)
    label_order = sorted(arch_map.keys(), key=lambda L: np.mean([d["cy"] for d in arch_map[L]]))
    arches = {arch_id + 1: arch_map[old_id] for arch_id, old_id in enumerate(label_order)}

    annot = img.copy()
    teeth_rows, gap_rows, cavein_rows = [], [], []
    px_per_mm = None

    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        if len(d_sorted) > USE_REF_TOOTH_IDX:
            ref_w_px = d_sorted[USE_REF_TOOTH_IDX]["w_px"]
            if ref_w_px > 0:
                px_per_mm = ref_w_px / KNOWN_MM_PER_TOOTH
            break

    for arch_id, dlist in arches.items():
        d_sorted = sorted(dlist, key=lambda d: d["cx"])
        col = COLOR_ARCH[(arch_id - 1) % len(COLOR_ARCH)]

        for idx, d in enumerate(d_sorted):
            cv2.polylines(annot, [d["pts"]], True, col, 2)
            label = f"A{arch_id}T{idx + 1}"
            cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.4, col, 1, cv2.LINE_AA)

            ch = d["poly"].convex_hull
            area_ratio = d["area_px"] / ch.area if ch.area > 0 else 1.0
            concavity = compute_concavity(d["poly"])
            is_cavein = (area_ratio < CAVEIN_AREA_RATIO) or (concavity > CAVEIN_CONCAVITY_THRESH)
            treatment, timeline = "N/A", "N/A"
            if is_cavein:
                cv2.putText(annot, "Cave-in", (int(d["cx"]), int(d["cy"])),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 0, 255), 1, cv2.LINE_AA)
                treatment = "Restoration (filling or buildup)" if area_ratio > 0.3 else "Endodontic + Crown or Extraction"
                timeline = "1-2 visits (2-4 weeks)" if area_ratio > 0.3 else "3-6 visits (4-12 weeks)"
                cavein_rows.append({
                    "arch": arch_id, "tooth": idx + 1,
                    "area_ratio": f"{area_ratio:.2f}", "concavity": f"{concavity:.2f}",
                    "treatment": treatment, "timeline": timeline,
                })

            teeth_rows.append({
                "arch": arch_id, "tooth": idx + 1, "class": d["class"],
                "confidence": f"{d['conf']:.2f}",
                "width_px": f"{d['w_px']:.1f}",
                "width_mm": f"{d['w_px'] / px_per_mm:.1f}" if px_per_mm else "N/A",
                "height_px": f"{d['h_px']:.1f}", "area_px": f"{d['area_px']:.1f}",
                "is_cavein": "Yes" if is_cavein else "No",
                "cavein_treatment": treatment, "cavein_timeline": timeline,
            })

        for i in range(len(d_sorted) - 1):
            gap_px = max(0, d_sorted[i + 1]["bx_min"] - d_sorted[i]["bx_max"])
            gap_mm = gap_px / px_per_mm if px_per_mm else None
            if gap_px > GAP_ALERT_PX:
                mid_x = int((d_sorted[i]["bx_max"] + d_sorted[i + 1]["bx_min"]) / 2)
                mid_y = int((d_sorted[i]["cy"] + d_sorted[i + 1]["cy"]) / 2)
                cv2.putText(annot, f"{gap_px:.0f}px", (mid_x, mid_y),
                            cv2.FONT_HERSHEY_SIMPLEX, 0.4, COLOR_GAP, 1, cv2.LINE_AA)
                if gap_px < 25:
                    cap_type, timeline = "Composite Resin Crown, Zirconia Crown, or PFM Crown", "2-3 weeks"
                elif gap_px < 50:
                    cap_type, timeline = "Zirconia or Porcelain-Fused-to-Metal Bridge", "3-6 weeks"
                else:
                    cap_type, timeline = "Multi-unit Bridge or Orthodontic Alignment + Prosthetics", "6-12+ weeks"
                gap_rows.append({
                    "arch": arch_id, "left_tooth": i + 1, "right_tooth": i + 2,
                    "gap_px": f"{gap_px:.1f}", "gap_mm": f"{gap_mm:.1f}" if gap_mm else "N/A",
                    "cap_type": cap_type, "timeline": timeline,
                })

    all_cx = np.array([d["cx"] for d in detections])
    align_std = np.std(all_cx)
    alignment = "Normal" if align_std < ALIGN_ALERT_PX else "Distracted (Misaligned)"
    misaligned_teeth = [f"A{row['arch']}T{row['tooth']}" for row in teeth_rows] if align_std >= ALIGN_ALERT_PX else []

    return annot, teeth_rows, gap_rows, cavein_rows, alignment, misaligned_teeth


# ============================================================
# --- Teeth-alignment analysis (model 3) ---
# ============================================================
# Model 3's workflow returns "Tooth" boxes alongside "Cavity"/"Caries"/
# "Crack" boxes. We reuse the tooth centers to measure alignment the same
# way model 1 does (spread of tooth-center x/y position vs. a fitted line
# through the arch), then map the severity to concrete correction options -
# both a *temporary* stabilizing option and the *permanent* fix.

ALIGNMENT_RULES = {
    "severe": {
        "temporary": ("Temporary stainless-steel arch wire (orthodontic wire) bonded across the "
                       "affected teeth, or a removable retainer, to stabilize position and stop further shifting",
                       "Fitted within 1-2 weeks"),
        "permanent": ("Fixed metal or ceramic braces, or full clear-aligner therapy (e.g. Invisalign-type system) "
                       "for complete correction; may include extraction/interproximal reduction if crowded",
                       "12-24 months"),
    },
    "moderate": {
        "temporary": ("Removable retainer, spacer, or partial stainless-steel wire to guide minor "
                       "repositioning and prevent worsening while a full plan is arranged",
                       "1-2 weeks to fit"),
        "permanent": ("Clear aligners or partial/segmental braces on the affected teeth",
                       "6-12 months"),
    },
    "mild": {
        "temporary": ("No immediate hardware needed; a retainer at night can prevent gradual shifting",
                       "N/A"),
        "permanent": ("Usually not required medically; cosmetic aligners are optional if desired",
                       "N/A"),
    },
}


def determine_alignment_severity(align_std):
    if align_std >= ALIGN_SEVERE_PX:
        return "severe"
    elif align_std >= ALIGN_MODERATE_PX:
        return "moderate"
    else:
        return "mild"


def analyze_teeth_workflow_alignment(detections, annot):
    """detections here is the full list from normalize_prediction_to_poly
    for model 3 (Tooth + Cavity + Caries + Crack boxes together)."""
    tooth_dets = [d for d in detections if "tooth" in (d["class"] or "").lower()]

    if len(tooth_dets) < 2:
        return None  # not enough tooth boxes to assess alignment

    tooth_sorted = sorted(tooth_dets, key=lambda d: d["cx"])
    all_cx = np.array([d["cx"] for d in tooth_sorted])
    all_cy = np.array([d["cy"] for d in tooth_sorted])

    # Fit a straight line through the arch and measure how far each tooth
    # center deviates from it - this is a better "misalignment" signal than
    # raw x spread, since it tolerates the natural curve/tilt of a normal arch.
    if len(tooth_sorted) >= 3:
        coeffs = np.polyfit(all_cx, all_cy, 1)
        predicted_y = np.polyval(coeffs, all_cx)
        deviations = np.abs(all_cy - predicted_y)
    else:
        deviations = np.abs(all_cy - np.mean(all_cy))

    align_std = float(np.std(deviations)) * 2  # scale to match ALIGN_* thresholds
    severity = determine_alignment_severity(align_std)
    status = "Normal" if severity == "mild" else f"Misaligned ({severity.capitalize()})"

    flagged = []
    mean_dev = float(np.mean(deviations)) if len(deviations) else 0.0
    dev_threshold = max(mean_dev * 1.5, 8.0)

    for idx, (d, dev) in enumerate(zip(tooth_sorted, deviations)):
        label = f"T{idx + 1}"
        is_off = dev > dev_threshold and severity != "mild"
        color = (0, 0, 255) if is_off else COLOR_ALIGN
        cv2.polylines(annot, [d["pts"]], True, color, 2)
        cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.4, color, 1, cv2.LINE_AA)
        if is_off:
            flagged.append(label)

    temp_treatment, temp_timeline = ALIGNMENT_RULES[severity]["temporary"]
    perm_treatment, perm_timeline = ALIGNMENT_RULES[severity]["permanent"]

    home_care = ("Practice good oral hygiene around any wire/retainer, rinse with warm salt water if "
                 "gums feel irritated, and use over-the-counter orthodontic wax on any wire or bracket "
                 "edge that rubs the cheek or lip; an OTC pain reliever (ibuprofen or acetaminophen, "
                 "taken as directed on the packaging) can ease soreness after adjustment.")
    if severity == "mild":
        home_care = ("Maintain regular brushing/flossing and routine dental checkups; no orthodontic "
                      "hardware is currently indicated.")

    return {
        "status": status,
        "severity": severity,
        "align_score_px": f"{align_std:.1f}",
        "flagged_teeth": ", ".join(flagged) if flagged else "None",
        "temp_treatment": temp_treatment, "temp_timeline": temp_timeline,
        "perm_treatment": perm_treatment, "perm_timeline": perm_timeline,
        "home_care": home_care,
    }


# ============================================================
# --- Treatment-suggestion rules (models 2, 3, 4) ---
# ============================================================
# Severity is inferred from shape irregularity (area_ratio / concavity),
# same signals already used for cave-in detection in the tooth model.
# Class-name matching is a simple substring/keyword match against whatever
# label your model returns, so it degrades gracefully to DEFAULT_TREATMENT
# if a class name isn't in the table below.

def determine_severity(area_ratio, concavity):
    if area_ratio < 0.30 or concavity > 0.35:
        return "severe"
    elif area_ratio < CAVEIN_AREA_RATIO or concavity > CAVEIN_CONCAVITY_THRESH:
        return "moderate"
    else:
        return "mild"


