def lookup_home_care(model_key, det_class):
    cls_lower = (det_class or "").lower()
    for keywords, tip in HOME_CARE_RULES.get(model_key, []):
        if any(k in cls_lower for k in keywords):
            return tip
    return DEFAULT_HOME_CARE


def suggest_treatment(model_key, det_class, area_ratio, concavity):
    """For detection/segmentation results: severity inferred from shape irregularity.
    Returns (treatment, timeline, home_care)."""
    severity = determine_severity(area_ratio, concavity)
    treatment, timeline = lookup_treatment(model_key, det_class, severity)
    home_care = lookup_home_care(model_key, det_class)
    return treatment, timeline, home_care


def determine_severity_from_confidence(cls_name, confidence):
    """For classification results: severity inferred from the model's own
    confidence in a non-normal class (there's no shape to measure)."""
    if any(k in (cls_name or "").lower() for k in ["normal", "healthy"]):
        return "mild"
    if confidence >= 0.75:
        return "severe"
    elif confidence >= 0.45:
        return "moderate"
    return "mild"


def suggest_treatment_classification(model_key, det_class, confidence):
    """Returns (treatment, timeline, home_care)."""
    severity = determine_severity_from_confidence(det_class, confidence)
    treatment, timeline = lookup_treatment(model_key, det_class, severity)
    home_care = lookup_home_care(model_key, det_class)
    return treatment, timeline, home_care


def analyze_classification_model(model_key, class_rows, img):
    """Generic fallback for classification-style responses with no boxes to
    draw: overlay predicted classes as text and build a class -> treatment table."""
    annot = img.copy()
    rows = []
    y = 30
    for entry in class_rows:
        cls, conf = entry["class"], entry["confidence"]
        treatment, timeline, home_care = suggest_treatment_classification(model_key, cls, conf)
        cv2.putText(annot, f"{cls}: {conf * 100:.1f}%", (10, y),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.6, COLOR_GENERIC, 2, cv2.LINE_AA)
        y += 28
        rows.append({
            "class": cls, "confidence": f"{conf * 100:.1f}%",
            "treatment": treatment, "timeline": timeline, "home_care": home_care,
        })
    return annot, rows


# ============================================================
# --- Tongue-specific interpretation (model 4) ---
# ============================================================

def parse_tongue_attribute(cls_name):
    """'colorResult_white' -> ('color', 'white')."""
    if "Result_" in cls_name:
        category, value = cls_name.split("Result_", 1)
    else:
        category, value = cls_name, cls_name
    return category.strip().lower(), value.strip()


