DEFAULT_TONGUE_MEANING = "This attribute doesn't strongly indicate a specific condition on its own."
DEFAULT_TONGUE_HOME_CARE = "General self-care: stay hydrated, maintain oral hygiene, and monitor for changes."


def analyze_tongue_classification(class_rows, img):
    """class_rows is already sorted by confidence desc (see
    normalize_classification_predictions), so the first entry seen for a
    given category is that category's top prediction."""
    annot = img.copy()
    top_by_category = {}
    all_rows = []

    for entry in class_rows:
        cls, conf = entry["class"], entry["confidence"]
        category, value = parse_tongue_attribute(cls)
        all_rows.append({"category": category.capitalize(), "value": value, "confidence": f"{conf * 100:.1f}%"})
        if category not in top_by_category:
            top_by_category[category] = (value, conf)

    top_rows = []
    for category, (value, conf) in top_by_category.items():
        meaning, home_care = TONGUE_INTERPRETATION.get(category, {}).get(
            value.lower(), (DEFAULT_TONGUE_MEANING, DEFAULT_TONGUE_HOME_CARE)
        )
        top_rows.append({
            "category": category.capitalize(), "value": value, "confidence": f"{conf * 100:.1f}%",
            "meaning": meaning, "home_care": home_care,
        })

    if top_rows:
        headline = f"Top finding: {top_rows[0]['category']} - {top_rows[0]['value']} ({top_rows[0]['confidence']})"
        cv2.putText(annot, headline, (10, 30), cv2.FONT_HERSHEY_SIMPLEX, 0.6, COLOR_GENERIC, 2, cv2.LINE_AA)

    return annot, top_rows, all_rows


# ============================================================
# --- Generic analysis (model 2, and per-detection findings for model 3) ---
# ============================================================

def analyze_generic_model(model_key, detections, img):
    annot = img.copy()
    rows, notable_rows = [], []

    for idx, d in enumerate(sorted(detections, key=lambda d: (d["cy"], d["cx"]))):
        cv2.polylines(annot, [d["pts"]], True, COLOR_GENERIC, 2)
        label = f"{d['class']} #{idx + 1} ({d['conf']:.2f})"
        cv2.putText(annot, label, (int(d["bx_min"]), max(int(d["by_min"]) - 5, 0)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.45, COLOR_GENERIC, 1, cv2.LINE_AA)

        ch = d["poly"].convex_hull
        area_ratio = d["area_px"] / ch.area if ch.area > 0 else 1.0
        concavity = compute_concavity(d["poly"])
        is_notable = (area_ratio < CAVEIN_AREA_RATIO) or (concavity > CAVEIN_CONCAVITY_THRESH)

        treatment, timeline, home_care = suggest_treatment(model_key, d["class"], area_ratio, concavity)

        if is_notable:
            cv2.putText(annot, "Irregular", (int(d["cx"]), int(d["cy"])),
                        cv2.FONT_HERSHEY_SIMPLEX, 0.4, (0, 0, 255), 1, cv2.LINE_AA)
            notable_rows.append({
                "index": idx + 1, "class": d["class"],
                "area_ratio": f"{area_ratio:.2f}", "concavity": f"{concavity:.2f}",
                "treatment": treatment, "timeline": timeline, "home_care": home_care,
            })

        rows.append({
            "index": idx + 1, "class": d["class"], "confidence": f"{d['conf']:.2f}",
            "width_px": f"{d['w_px']:.1f}", "height_px": f"{d['h_px']:.1f}",
            "area_px": f"{d['area_px']:.1f}", "is_notable": "Yes" if is_notable else "No",
            "treatment": treatment, "timeline": timeline, "home_care": home_care,
        })

    return annot, rows, notable_rows


def analyze_teeth_workflow_model(detections, img):
    """Model 3 wrapper: per-detection cavity/caries/crack findings PLUS a
    dedicated alignment assessment built from the 'Tooth' boxes."""
    annot, rows, notable_rows = analyze_generic_model("3", detections, img)
    alignment = analyze_teeth_workflow_alignment(detections, annot)
    return annot, rows, notable_rows, alignment


